318	export const DEFAULT_EFFECTS: Record<CategoryKey, EffectKey[]> = {
319	  weapons: ["storm", "fire", "frost"],
320	  creatures: ["void", "poison", "summon"],
321	  worlds: ["lunar", "frost"],
322	  mechanics: ["auto", "neon"],
323	  shaders: ["lunar", "neon"],
324	  magic: ["storm", "lunar", "frost"],
325	  quests: ["lunar", "void"],
326	  interface: ["neon", "auto"],
327	  audio: ["lunar", "neon"],
328	  vehicles: ["flight", "neon"],
329	  items: ["auto", "heal"],
330	  characters: ["heal", "lunar"],
331	};
332	
333	export function effectsFor(input: TemplateInput): Effect[] {
334	  const text = `${input.prompt} ${input.modName}`.toLowerCase();
335	  const hits = EFFECTS.filter((e) => e.re.test(text)).slice(0, 2);
336	  if (hits.length) return hits;
337	  const pool = DEFAULT_EFFECTS[input.category.key];
338	  const key = pool[hashStr(input.modName) % pool.length];
339	  return [EFFECTS.find((e) => e.key === key)!];
340	}
341	
342	export const sub = (s: string, target: string, source: string, extra: Record<string, string> = {}) => {
343	  let out = s.replaceAll("TARGET", target).replaceAll("SOURCE_SRC", extra.SOURCE_SRC ?? "source").replaceAll("SOURCE", source);
344	  for (const [k, v] of Object.entries(extra)) out = out.replaceAll(k, v);
345	  return out;
346	};
347	
348	export type Arch = "item" | "entity" | "world" | "system" | "visual";
