350	  weapons: "item",
351	  items: "item",
352	  magic: "item",
353	  creatures: "entity",
354	  characters: "entity",
355	  vehicles: "entity",
356	  worlds: "world",
357	  mechanics: "system",
358	  quests: "system",
359	  interface: "system",
360	  audio: "system",
361	  shaders: "visual",
362	};
363	
364	export const MODEL_NAME: Record<ModelId, string> = { katara: "Katara", sokka: "Sokka", yako: "Yako" };
365	
366	export function deriveFeatures(input: TemplateInput): string[] {
367	  const n = numbers(input);
368	  const fx = effectsFor(input).map((e) => e.label);
369	  const cat = input.category.key;
370	  const byCat: Record<CategoryKey, string> = {
371	    weapons: `${n.power} bonus damage with a ${n.cooldown}s active ability`,
