/**
 * Rust · Oxide/uMod (Carbon-compatible) · C#. One plugin file per mod; config/lang JSON mirror what Oxide writes on
 * first load. Branches on the category archetype, and on Rust intent ("raid alarm", "minicopter") when the router
 * fell back to the default category.
 */
import type { CategoryKey, ModFile } from "@/lib/types";
import { ARCH, code, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

type Nums = ReturnType<typeof numbers>;
type Val = number | string | boolean | string[] | Record<string, number>;
interface Opt { key: string; name: string; v: Val; t?: "int" | "ulong" }
interface Fx { apply: string; member?: string; opts?: (n: Nums) => Opt[]; msgs?: Record<string, string> }
interface Mode {
  label: string;
  desc: string;
  fields?: string[];
  init?: string[];
  start?: string[];
  save?: string[];
  unload?: string[];
  hooks?: string;
  commands: string;
  logic?: string;
  opts: Opt[];
  msgs: Record<string, string>;
  api: string;
  check: string;
  extra?: ModFile[];
}

const opt = (key: string, name: string, v: Val, t?: Opt["t"]): Opt => ({ key, name, v, t });
const r2 = (x: number) => Math.round(x * 100) / 100;
const pick = (table: [RegExp, string][], text: string, fallback: string) => table.find(([re]) => re.test(text))?.[1] ?? fallback;
const join = (...parts: (string | false | undefined)[]) => parts.filter((p): p is string => !!p).map((p) => p.replace(/\n+$/, "")).join("\n\n");
const region = (name: string, body: string) => (body.trim() ? `#region ${name}\n\n${body.replace(/\n+$/, "")}\n\n#endregion` : "");
const jsonFloat = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

function csType(o: Opt) {
  if (o.t) return o.t;
  if (typeof o.v === "number") return "float";
  if (typeof o.v === "boolean") return "bool";
  if (typeof o.v === "string") return "string";
  return Array.isArray(o.v) ? "List<string>" : "Dictionary<string, float>";
}
function csValue(o: Opt) {
  const v = o.v;
  if (typeof v === "number") return o.t ? `${v}${o.t === "ulong" ? "UL" : ""}` : `${v}f`;
  if (typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return `new List<string> { ${v.map((s) => JSON.stringify(s)).join(", ")} }`;
  return `new Dictionary<string, float>\n{\n${Object.entries(v).map(([k, x]) => `    [${JSON.stringify(k)}] = ${x}f`).join(",\n")}\n}`;
}
function jsonValue(o: Opt) {
  const v = o.v;
  if (typeof v === "number") return o.t ? String(v) : jsonFloat(v);
  if (typeof v !== "object" || Array.isArray(v)) return JSON.stringify(v, null, 2);
  return `{\n${Object.entries(v).map(([k, x]) => `  ${JSON.stringify(k)}: ${jsonFloat(x)}`).join(",\n")}\n}`;
}

/** Real prefab paths, declared as consts only when the generated plugin uses them. */
const ASSETS: Record<string, string> = {
  FxShock: "assets/prefabs/locks/keypad/effects/lock.code.shock.prefab",
  FxExplosion: "assets/bundled/prefabs/fx/explosions/explosion_03.prefab",
  FxBlink: "assets/prefabs/misc/halloween/lootbag/effects/silver_open.prefab",
  FxPoison: "assets/bundled/prefabs/fx/gestures/drink_vomit.prefab",
  FxCast: "assets/prefabs/misc/xmas/presents/effects/unwrap.prefab",
  FxHeadshot: "assets/bundled/prefabs/fx/headshot.prefab",
  FxAlarm: "assets/bundled/prefabs/fx/invite_notice.prefab",
  FxSuccess: "assets/prefabs/deployable/research table/effects/research-success.prefab",
  FxBoost: "assets/prefabs/npc/patrol helicopter/effects/rocket_fire.prefab",
  PrefabFireball: "assets/bundled/prefabs/fireball_small.prefab",
  PrefabCrate: "assets/prefabs/deployable/chinooklockedcrate/codelockedhackablecrate.prefab",
};
const SCIENTIST = "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_roam.prefab";

/** Each prompt effect as Oxide code inside ApplyEffects(attacker, target, info); `member` adds hooks/methods it needs. */
const FX: Record<EffectKey, Fx> = {
  frost: {
    apply: code`
      // Frost: chill them to the bone; Rust's own cold damage does the rest.
      if (target != null)
      {
          Damage(target, attacker, info, DamageType.Cold, config.EffectPower);
          if (victim != null)
          {
              victim.metabolism.temperature.SetValue(-config.EffectPower * 2f);
              victim.metabolism.wetness.Add(0.6f);
              victim.metabolism.SendChangesToClient();
          }
      }`,
  },
  fire: {
    apply: code`
      // Fire: leave a burning fireball where they stand.
      if (target != null)
      {
          Damage(target, attacker, info, DamageType.Heat, config.EffectPower);
          var fireball = GameManager.server.CreateEntity(PrefabFireball, pos) as FireBall;
          if (fireball != null)
          {
              fireball.lifeTimeMin = fireball.lifeTimeMax = config.EffectSeconds;
              fireball.Spawn();
          }
      }`,
  },
  storm: {
    apply: code`
      // Storm: shock the target, then arc to anyone standing close by.
      if (target != null)
      {
          Damage(target, attacker, info, DamageType.ElectricShock, config.EffectPower);
          Effect.server.Run(FxShock, pos);
          Effect.server.Run(FxExplosion, pos);
          var arcs = new List<BasePlayer>();
          Vis.Entities(pos, config.EffectRadius, arcs, Layers.Mask.Player_Server);
          foreach (var other in arcs)
          {
              if (other == target || other == attacker || other.IsSleeping() || IsAlly(caster, other)) continue;
              Effect.server.Run(FxShock, other.transform.position);
              other.Hurt(config.EffectPower * 0.5f, DamageType.ElectricShock, attacker);
          }
      }`,
  },
  blink: {
    apply: code`
      // Blink: step through space to just behind the target.
      if (caster != null && target != null && !caster.isMounted)
      {
          var behind = pos - target.transform.forward * 1.5f;
          behind.y = Mathf.Max(behind.y, TerrainMeta.HeightMap.GetHeight(behind));
          Effect.server.Run(FxBlink, caster.transform.position);
          caster.Teleport(behind);
          Effect.server.Run(FxBlink, behind);
      }`,
  },
  heal: {
    apply: code`
      // Heal: every proc patches the attacker up and stops the bleeding.
      if (attacker != null && !attacker.IsDead())
      {
          attacker.Heal(config.EffectPower * 0.5f);
          if (caster != null) caster.metabolism.bleeding.SetValue(0f);
      }`,
  },
  poison: {
    apply: code`
      // Poison: venom keeps working long after the hit.
      if (victim != null)
      {
          victim.metabolism.poison.Add(config.EffectPower);
          victim.metabolism.SendChangesToClient();
          Effect.server.Run(FxPoison, pos);
      }
      else if (target != null) Damage(target, attacker, info, DamageType.Poison, config.EffectPower);`,
  },
  summon: {
    apply: code`
      // Summon: echoes spawn around the target and fight for the attacker.
      for (var i = 0; i < config.SummonCount; i++)
      {
          var spot = pos + Random.insideUnitSphere.WithY(0f) * config.EffectRadius;
          spot.y = TerrainMeta.HeightMap.GetHeight(spot);
          var echo = GameManager.server.CreateEntity(config.SummonPrefab, spot) as BaseCombatEntity;
          if (echo == null) continue;
          echo.Spawn();
          var id = echo.net.ID.Value;
          if (caster != null) summonOwners[id] = caster.userID.Get();
          timer.Once(config.EffectSeconds * 3f, () =>
          {
              summonOwners.Remove(id);
              if (echo != null && !echo.IsDestroyed) echo.Kill();
          });
      }`,
    opts: (n) => [opt("Summon count", "SummonCount", 1 + (n.radius % 3), "int"), opt("Summon prefab", "SummonPrefab", SCIENTIST)],
  },
  flight: {
    apply: code`
      // Flight: launch the attacker skywards, or the vehicle they're driving.
      if (caster != null)
      {
          var ride = caster.GetMountedVehicle();
          if (ride != null && ride.rigidBody != null) ride.rigidBody.AddForce(Vector3.up * config.LiftForce, ForceMode.VelocityChange);
          else if (!caster.isMounted) caster.ApplyInheritedVelocity(caster.eyes.HeadForward() * 4f + Vector3.up * config.LiftForce);
      }`,
    opts: (n) => [opt("Lift force (m/s)", "LiftForce", r2(n.speed * 25))],
  },
  void: {
    apply: code`
      // Void: open a wound and black out their screen for a moment.
      if (target != null)
      {
          Damage(target, attacker, info, DamageType.Bleeding, config.EffectPower * 0.5f);
          if (victim != null && victim.IsConnected)
          {
              victim.metabolism.bleeding.Add(config.EffectPower);
              victim.metabolism.SendChangesToClient();
              var veil = new CuiElementContainer();
              veil.Add(new CuiPanel { Image = { Color = "0 0 0 0.94", FadeIn = 0.3f }, RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }, FadeOut = 1.5f }, "Overlay", UiVoid);
              CuiHelper.DestroyUi(victim, UiVoid);
              CuiHelper.AddUi(victim, veil);
              timer.Once(config.EffectSeconds, () => { if (victim != null && victim.IsConnected) CuiHelper.DestroyUi(victim, UiVoid); });
          }
      }`,
  },
  lunar: {
    apply: code`
      // Lunar: after dark every proc hits harder.
      if (target != null && TOD_Sky.Instance.IsNight)
      {
          if (info != null) info.damageTypes.ScaleAll(1f + config.NightBonus);
          else target.Hurt(config.EffectPower * config.NightBonus, DamageType.Generic, attacker);
          Effect.server.Run(FxCast, pos);
      }`,
    opts: (n) => [opt("Night damage bonus (0-1)", "NightBonus", r2(n.intensity / 2))],
  },
  auto: {
    apply: code`
      // Auto: the tool or weapon in hand repairs itself as it works.
      if (caster != null)
      {
          var held = caster.GetActiveItem();
          if (held != null && held.hasCondition) held.condition = Mathf.Min(held.maxCondition, held.condition + config.EffectPower);
      }`,
    member: code`
      private void OnDispenserGather(ResourceDispenser dispenser, BaseEntity entity, Item item)
      {
          var player = entity?.ToPlayer();
          if (player == null || item == null || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
          item.amount = Mathf.CeilToInt(item.amount * config.GatherMultiplier);
      }`,
    opts: (n) => [opt("Gather multiplier", "GatherMultiplier", r2(1 + n.power / 10))],
  },
  neon: {
    apply: code`
      // Neon: a HUD flash tells the attacker the effect fired.
      if (caster != null && caster.IsConnected) Flash(caster, Lang("Proc", caster.UserIDString, Title));`,
    member: code`
      private void Flash(BasePlayer player, string text)
      {
          var ui = new CuiElementContainer();
          ui.Add(new CuiPanel { Image = { Color = "1 0.4 0.85 0.85", FadeIn = 0.15f }, RectTransform = { AnchorMin = "0.38 0.86", AnchorMax = "0.62 0.91" }, FadeOut = 0.4f }, "Hud", UiFlash);
          ui.Add(new CuiLabel { Text = { Text = text, FontSize = 13, Align = TextAnchor.MiddleCenter, Font = "robotocondensed-bold.ttf" }, RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" } }, UiFlash);
          CuiHelper.DestroyUi(player, UiFlash);
          CuiHelper.AddUi(player, ui);
          timer.Once(2f, () => { if (player != null && player.IsConnected) CuiHelper.DestroyUi(player, UiFlash); });
      }`,
    msgs: { Proc: "<color=#ff66d9>{0}</color> overcharged" },
  },
};

const WEAPON_BASE: [RegExp, string][] = [
  [/crossbow/, "crossbow"], [/bow|arrow/, "bow.compound"], [/rail|sniper|pierc/, "rifle.l96"], [/shotgun|scatter/, "shotgun.spas12"],
  [/revolver|pistol/, "pistol.python"], [/smg|uzi/, "smg.mp5"], [/rocket|launcher/, "rocket.launcher"], [/flame/, "flamethrower"],
  [/sword|blade|katana/, "longsword"], [/axe/, "axe.salvaged"], [/hammer|mace/, "mace"], [/spear|glaive/, "spear.stone"], [/knife|dagger/, "knife.combat"],
];
const TOOL_BASE: [RegExp, string][] = [[/pick|mine|ore/, "pickaxe"], [/axe|chop|wood/, "hatchet"], [/heal|med|syringe|potion/, "syringe.medical"], [/torch|lantern|light/, "torch"], [/drill|jack/, "jackhammer"], [/saw/, "chainsaw"]];
const FOCUS_BASE: [RegExp, string][] = [[/staff|rod|wand/, "spear.wooden"], [/skull|necro/, "skull.human"], [/torch|flame|fire/, "torch"]];
const CREATURES: [RegExp, string][] = [
  [/polar/, "assets/rust.ai/agents/bear/polarbear.prefab"], [/wolf|hound/, "assets/rust.ai/agents/wolf/wolf.prefab"], [/boar|pig/, "assets/rust.ai/agents/boar/boar.prefab"],
  [/stag|deer/, "assets/rust.ai/agents/stag/stag.prefab"], [/shark/, "assets/rust.ai/agents/fish/simpleshark.prefab"], [/chicken/, "assets/rust.ai/agents/chicken/chicken.prefab"],
];
const VEHICLES: [RegExp, string][] = [
  [/scrap|transport/, "assets/content/vehicles/scrap heli carrier/scraptransporthelicopter.prefab"],
  [/mini|copter|heli|fly|flight/, "assets/content/vehicles/minicopter/minicopter.entity.prefab"],
  [/rhib/, "assets/content/vehicles/boats/rhib/rhib.prefab"], [/boat|ship|raft|sea/, "assets/content/vehicles/boats/rowboat/rowboat.prefab"],
  [/submarine/, "assets/content/vehicles/submarine/submarinesolo.entity.prefab"], [/snow/, "assets/content/vehicles/snowmobiles/snowmobile.prefab"],
  [/bike|motor/, "assets/content/vehicles/bikes/motorbike.prefab"], [/horse/, "assets/rust.ai/nextai/testridablehorse.prefab"],
];
/** When the router fell back to Rust's default category, the prompt's Rust nouns pick the archetype instead. */
const WEAPONISH = /rifle|rocket|launcher|railgun|pistol|shotgun|smg|\bak\b|bow|sword|spear|knife|c4|explosive/;
const RAID = /raid|alarm|\bbase\b|cupboard|\btc\b|code ?lock|door/;
const INTENTS: [RegExp, CategoryKey][] = [
  [RAID, "mechanics"], [/minicopter|copter|heli\b|rhib|boat|\bcar\b|horse|bike|snowmobile|submarine|vehicle/, "vehicles"],
  [/scientist|companion|follower|bodyguard|\bnpc|bandit/, "characters"], [/monument|event|airdrop|oil ?rig|cargo/, "worlds"],
  [/gather|harvest|farm|quarry|rates?\b|loot/, "mechanics"], [/hud|\bui\b|overlay|scoreboard|panel/, "interface"],
];

export function rustOxide(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const title = input.modName.replace(/"/g, "'");
  const model = MODEL_NAME[input.model];
  const rich = input.model !== "katara";
  const deep = input.model === "yako";
  const lc = cls.toLowerCase();
  const cmd = snake.split("_").slice(-2).join("");
  const acc = "#" + fxs[0].tint.map((c) => Math.round(c * 255).toString(16).padStart(2, "0")).join("");
  const explicitFx = fxs.some((e) => e.re.test(text));

  let k = input.category.key;
  if (!input.category.keywords.some((w) => new RegExp(`\\b${w}`).test(text)) && !WEAPONISH.test(text)) k = INTENTS.find(([re]) => re.test(text))?.[1] ?? k;
  const arch = ARCH[k];
  const gather = k === "mechanics" && !RAID.test(text) && /gather|harvest|farm|quarry|rate|loot|resource|auto/.test(text);
  const toggle = (refresh: string) => code`
    [ChatCommand("${cmd}")]
    private void CmdToggle(BasePlayer player, string command, string[] args)
    {
        if (!permission.UserHasPermission(player.UserIDString, PermUse))
        {
            Reply(player, "NoPermission");
            return;
        }
        var id = player.userID.Get();
        if (!optedOut.Remove(id)) optedOut.Add(id);
        ${refresh}
        Reply(player, optedOut.Contains(id) ? "Off" : "On");
    }`;
  const prefs = { fields: ["private HashSet<ulong> optedOut;"], init: ["optedOut = Interface.Oxide.DataFileSystem.ReadObject<HashSet<ulong>>(Name) ?? new HashSet<ulong>();"], save: ["Interface.Oxide.DataFileSystem.WriteObject(Name, optedOut);"] };
  const snapshotWait = (call: string) => code`
    private void OnPlayerConnected(BasePlayer player)
    {
        if (player.IsReceivingSnapshot)
        {
            timer.Once(1f, () => OnPlayerConnected(player));
            return;
        }
        ${call}
    }`;

  let m: Mode;
  if (arch === "item") {
    const weapon = k === "weapons";
    const magic = k === "magic";
    const base = weapon ? pick(WEAPON_BASE, text, "rifle.ak") : magic ? pick(FOCUS_BASE, text, "bone.club") : pick(TOOL_BASE, text, "rock");
    const pierce = weapon && /pierc|wall|rail|breach|raid/.test(text);
    m = {
      label: "Custom Item",
      desc: `${title}: a skinned ${base} ${weapon ? "whose hits" : magic ? "that casts spells which" : "with an ability that"} ${fxs.map((e) => e.label.toLowerCase()).join(" and ")}`,
      hooks: weapon
        ? code`
          private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
          {
              var attacker = info?.InitiatorPlayer;
              if (attacker == null || entity == null || !IsCustom(info.Weapon?.GetItem())) return null;
              if (!permission.UserHasPermission(attacker.UserIDString, PermUse)) return null;

              info.damageTypes.ScaleAll(${pierce ? "entity is BuildingBlock ? config.StructureMultiplier : config.DamageMultiplier" : "config.DamageMultiplier"});
              if (info.isHeadshot) EffectNetwork.Send(new Effect(FxHeadshot, attacker, 0, Vector3.zero, Vector3.zero), attacker.net.connection);
              if (Random.value <= config.ProcChance && !OnCooldown(attacker)) ApplyEffects(attacker, entity, info);
              return null;
          }

          private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
          {
              if (player != null && IsCustom(newItem) && permission.UserHasPermission(player.UserIDString, PermUse)) Reply(player, "Equipped", config.DisplayName);
          }

          private void OnLootSpawn(LootContainer container)
          {
              if (container == null || !config.LootContainers.Contains(container.ShortPrefabName) || Random.value > config.LootChance) return;
              NextTick(() =>
              {
                  if (container == null || container.IsDestroyed || container.inventory == null) return;
                  if (container.inventory.itemList.Count >= container.inventory.capacity) container.inventory.capacity++;
                  CreateItem()?.MoveToContainer(container.inventory);
              });
          }`
        : code`
          private void OnPlayerInput(BasePlayer player, InputState input)
          {
              if (player == null || input == null || !input.WasJustPressed(BUTTON.FIRE_THIRD)) return;
              var item = player.GetActiveItem();
              if (!IsCustom(item) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
              ${magic ? `if (player.metabolism.calories.value < config.CalorieCost)\n{\n    Reply(player, "Exhausted", config.CalorieCost);\n    return;\n}` : ""}
              if (OnCooldown(player, true)) return;

              RaycastHit hit;
              ${
                magic
                  ? code`
                    var point = Physics.Raycast(player.eyes.HeadRay(), out hit, config.Range, Layers.Solid) ? hit.point : player.eyes.position + player.eyes.HeadForward() * config.Range;
                    player.metabolism.calories.Subtract(config.CalorieCost);
                    player.metabolism.SendChangesToClient();
                    Effect.server.Run(FxCast, point);

                    var caught = new List<BaseCombatEntity>();
                    Vis.Entities(point, config.EffectRadius, caught);
                    caught.RemoveAll(e => e == player || IsAlly(player, e as BasePlayer));
                    if (caught.Count == 0) ApplyEffects(player, null);
                    foreach (var target in caught) ApplyEffects(player, target);`
                  : code`
                    var target = Physics.Raycast(player.eyes.HeadRay(), out hit, config.Range, Layers.Solid | Layers.Mask.Player_Server) ? hit.GetEntity() as BaseCombatEntity : null;
                    ApplyEffects(player, target);
                    item.LoseCondition(config.ConditionCost);`
              }
          }

          private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
          {
              if (player != null && IsCustom(newItem) && permission.UserHasPermission(player.UserIDString, PermUse)) Reply(player, "Equipped", config.DisplayName);
          }

          private void OnItemCraftFinished(ItemCraftTask task, Item item, ItemCrafter crafter)
          {
              var player = task?.owner;
              if (player == null || item == null || item.info.shortname != config.Shortname || IsCustom(item)) return;
              if (!permission.UserHasPermission(player.UserIDString, PermUse) || Random.value > config.CraftChance) return;
              Brand(item);
              Reply(player, "Crafted", config.DisplayName);
          }`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdGive(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermAdmin))
            {
                Reply(player, "NoPermission");
                return;
            }
            var target = args.Length > 0 ? BasePlayer.Find(args[0]) : player;
            if (target == null)
            {
                Reply(player, "PlayerNotFound", args[0]);
                return;
            }
            var item = CreateItem();
            if (item == null) return;
            target.GiveItem(item);
            Reply(player, "Given", config.DisplayName, target.displayName);
        }

        [ConsoleCommand("${cmd}.give")]
        private void CcmdGive(ConsoleSystem.Arg arg)
        {
            if (!arg.IsAdmin) return;
            var target = BasePlayer.Find(arg.GetString(0));
            if (target == null)
            {
                arg.ReplyWith("Usage: ${cmd}.give <name or steamid>");
                return;
            }
            var item = CreateItem();
            if (item != null) target.GiveItem(item);
            arg.ReplyWith($"Gave {config.DisplayName} to {target.displayName}");
        }`,
      logic: code`
        private Item CreateItem(int amount = 1)
        {
            var item = ItemManager.CreateByName(config.Shortname, amount, config.SkinId);
            if (item == null)
            {
                PrintError($"Unknown item shortname '{config.Shortname}', check the config");
                return null;
            }
            Brand(item);
            return item;
        }

        private void Brand(Item item)
        {
            item.skin = config.SkinId;
            item.name = config.DisplayName;
            var held = item.GetHeldEntity();
            if (held != null)
            {
                held.skinID = config.SkinId;
                held.SendNetworkUpdate();
            }
            item.MarkDirty();
        }

        private bool IsCustom(Item item) => item != null && item.skin == config.SkinId && item.info.shortname == config.Shortname;`,
      opts: [
        opt("Item shortname", "Shortname", base),
        opt("Skin ID", "SkinId", 2_000_000_000 + (hashStr(cls) % 999_999_999), "ulong"),
        opt("Display name", "DisplayName", title),
        opt("Damage multiplier", "DamageMultiplier", r2(1 + n.power / 20)),
        opt("Damage multiplier vs. structures", "StructureMultiplier", r2(1.5 + n.power / 10)),
        opt("Effect chance per hit (0-1)", "ProcChance", n.chance),
        opt("Loot chance per crate (0-1)", "LootChance", r2(n.chance / 5)),
        opt("Loot containers", "LootContainers", ["crate_elite", "crate_normal", "heli_crate", "bradley_crate"]),
        opt("Craft chance (0-1)", "CraftChance", n.chance),
        opt("Range (meters)", "Range", n.radius * 8),
        opt("Condition lost per use", "ConditionCost", r2(n.power / 2)),
        opt("Calories per cast", "CalorieCost", Math.round(n.power * 5)),
      ],
      msgs: {
        Equipped: weapon
          ? `<color=${acc}>{0}</color> equipped: ${fxs.map((e) => e.label.toLowerCase()).join(", ")}.`
          : `<color=${acc}>{0}</color> in hand. Press <color=${acc}>middle mouse</color> to ${magic ? "cast" : "use it"}.`,
        Given: "Gave <color=" + acc + ">{0}</color> to {1}.",
        Crafted: `Your craft turned out to be <color=${acc}>{0}</color>!`,
        Exhausted: "Too hungry to cast, you need {0} calories.",
      },
      api: "private Item API_CreateItem(int amount = 1) => CreateItem(amount);",
      check: code`
        var item = ${cls}.Call("API_CreateItem", 1) as Item;
        Check(failures, "API_CreateItem returns a branded item", item != null && item.skin != 0UL);
        item?.Remove();`,
    };
  } else if (k === "creatures") {
    m = {
      label: "Mutants",
      desc: `${title}: mutated ${pick(CREATURES, text, "bear").split("/").pop()!.replace(".prefab", "")}s with boosted health that ${fxs[0].label.toLowerCase()}`,
      fields: ["private readonly HashSet<BaseCombatEntity> mutants = new HashSet<BaseCombatEntity>();", "private readonly HashSet<BaseCombatEntity> enraged = new HashSet<BaseCombatEntity>();"],
      unload: ["foreach (var mutant in mutants.ToList()) if (mutant != null && !mutant.IsDestroyed) mutant.Kill();"],
      hooks: code`
        private void OnEntitySpawned(BaseCombatEntity entity)
        {
            if (entity == null || entity.PrefabName != config.Prefab || Random.value > config.SpawnChance) return;
            NextTick(() => Mutate(entity));
        }

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null || info == null) return null;
            var attacker = info.Initiator as BaseCombatEntity;
            if (attacker != null && mutants.Contains(attacker) && entity is BasePlayer)
            {
                info.damageTypes.ScaleAll(config.DamageMultiplier);
                ApplyEffects(attacker, entity, info);
            }
            else if (mutants.Contains(entity) && entity.health - info.damageTypes.Total() < entity.MaxHealth() * config.EnrageAt && enraged.Add(entity))
            {
                Broadcast("Enraged", PhoneController.PositionToGridName(entity.transform.position));
            }
            return null;
        }

        private void OnEntityDeath(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null || !mutants.Remove(entity)) return;
            enraged.Remove(entity);
            ItemManager.CreateByName(config.LootShortname, config.LootAmount)?.Drop(entity.transform.position + Vector3.up, Vector3.up * 2f);
            var killer = info?.InitiatorPlayer;
            if (killer != null) Broadcast("Slain", killer.displayName);
        }`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdSpawn(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermAdmin))
            {
                Reply(player, "NoPermission");
                return;
            }
            var pos = player.transform.position + player.eyes.BodyForward() * 12f;
            pos.y = TerrainMeta.HeightMap.GetHeight(pos);
            var animal = GameManager.server.CreateEntity(config.Prefab, pos) as BaseCombatEntity;
            if (animal == null) return;
            animal.Spawn();
            Mutate(animal);
        }`,
      logic: code`
        private void Mutate(BaseCombatEntity animal)
        {
            if (animal == null || animal.IsDestroyed || !mutants.Add(animal)) return;
            animal.InitializeHealth(config.Health, config.Health);
            animal.SendNetworkUpdate();
            if (config.Announce) Broadcast("Spawned", PhoneController.PositionToGridName(animal.transform.position));
        }`,
      opts: [
        opt("Creature prefab", "Prefab", pick(CREATURES, text, "assets/rust.ai/agents/bear/bear.prefab")),
        opt("Mutation chance on natural spawns (0-1)", "SpawnChance", r2(n.chance / 2)),
        opt("Health", "Health", n.health * 2),
        opt("Damage multiplier", "DamageMultiplier", r2(1 + n.power / 10)),
        opt("Enrage below health fraction", "EnrageAt", 0.4),
        opt("Loot shortname", "LootShortname", "scrap"),
        opt("Loot amount", "LootAmount", n.xp * 3, "int"),
        opt("Announce spawns", "Announce", true),
        opt("Summon prefab", "SummonPrefab", pick(CREATURES, text, "assets/rust.ai/agents/bear/bear.prefab")),
      ],
      msgs: {
        Spawned: `A <color=${acc}>${title}</color> was sighted at {0}.`,
        Enraged: `The <color=${acc}>${title}</color> at {0} is enraged!`,
        Slain: `{0} brought down the <color=${acc}>${title}</color>.`,
      },
      api: "private bool API_IsMutant(BaseCombatEntity entity) => entity != null && mutants.Contains(entity);",
      check: `Check(failures, "API_IsMutant answers", ${cls}.Call("API_IsMutant", (BaseCombatEntity)null) is bool);`,
    };
  } else if (k === "characters") {
    m = {
      label: "Companions",
      desc: `${title}: a scientist companion that follows you and ${fxs[0].label.toLowerCase().replace("the wielder", "you")}`,
      fields: ["private readonly Dictionary<ulong, ScientistNPC> companions = new Dictionary<ulong, ScientistNPC>();"],
      start: ["timer.Every(1f, Follow);"],
      unload: ["foreach (var ownerId in companions.Keys.ToList()) Dismiss(ownerId);"],
      hooks: code`
        private void OnEntityTakeDamage(BasePlayer player, HitInfo info)
        {
            ScientistNPC npc;
            var attacker = info?.Initiator as BaseCombatEntity;
            if (attacker == null || attacker == player || player.IsNpc || !companions.TryGetValue(player.userID.Get(), out npc) || npc == null) return;
            if (attacker == npc || IsAlly(player, attacker as BasePlayer) || Vector3.Distance(npc.transform.position, attacker.transform.position) > config.AssistRange) return;
            ApplyEffects(npc, attacker);
        }

        private void OnEntityDeath(ScientistNPC npc, HitInfo info)
        {
            var ownerId = companions.FirstOrDefault(pair => pair.Value == npc).Key;
            if (ownerId == 0UL) return;
            companions.Remove(ownerId);
            summonOwners.Remove(npc.net.ID.Value);
            var owner = BasePlayer.FindByID(ownerId);
            if (owner != null) Reply(owner, "Fallen", config.CompanionName);
        }

        private void OnPlayerDisconnected(BasePlayer player, string reason) => Dismiss(player.userID.Get());`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdCompanion(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermUse))
            {
                Reply(player, "NoPermission");
                return;
            }
            if (companions.ContainsKey(player.userID.Get()))
            {
                Dismiss(player.userID.Get());
                Reply(player, "Dismissed", config.CompanionName);
                return;
            }
            if (OnCooldown(player, true)) return;

            var pos = player.transform.position + player.eyes.BodyForward() * 2f;
            var npc = GameManager.server.CreateEntity(config.Prefab, pos, player.transform.rotation) as ScientistNPC;
            if (npc == null) return;
            npc.Spawn();
            npc.displayName = config.CompanionName;
            npc.InitializeHealth(config.Health, config.Health);
            companions[player.userID.Get()] = npc;
            summonOwners[npc.net.ID.Value] = player.userID.Get();
            Reply(player, "Summoned", config.CompanionName);
        }`,
      logic: code`
        private void Follow()
        {
            foreach (var pair in companions.ToList())
            {
