        private bool StartEvent()
        {
            if (crate != null && !crate.IsDestroyed) return false;
            if (monuments.Count == 0 || BasePlayer.activePlayerList.Count < config.MinPlayers) return false;
            ${night ? "if (config.NightOnly && !TOD_Sky.Instance.IsNight) return false;" : ""}

            var monument = monuments[Random.Range(0, monuments.Count)];
            zone = monument.transform.position;
            crate = GameManager.server.CreateEntity(PrefabCrate, zone + Vector3.up) as HackableLockedCrate;
            if (crate == null) return false;
            crate.Spawn();
            for (var i = 0; i < config.Guards; i++)
            {
                var spot = zone + Random.insideUnitSphere.WithY(0f) * 12f;
                spot.y = TerrainMeta.HeightMap.GetHeight(spot);
                var guard = GameManager.server.CreateEntity(config.GuardPrefab, spot);
                if (guard == null) continue;
                guard.Spawn();
                guards.Add(guard);
            }
            pulse = timer.Every(config.PulseSeconds, Pulse);
            expiry = timer.Once(config.DurationMinutes * 60f, () => StopEvent(false));
            Broadcast("Started", monument.displayPhrase.english, PhoneController.PositionToGridName(zone));
            return true;
        }

        private void Pulse()
        {
            if (crate == null || crate.IsDestroyed)
            {
                StopEvent(true);
                return;
            }
            var inside = new List<BasePlayer>();
            Vis.Entities(zone, config.ZoneRadius, inside, Layers.Mask.Player_Server);
            foreach (var player in inside)
                if (!player.IsNpc && player.IsAlive()) ApplyEffects(null, player);
        }

        private void StopEvent(bool claimed)
        {
            pulse?.Destroy();
            expiry?.Destroy();
            foreach (var guard in guards) if (guard != null && !guard.IsDestroyed) guard.Kill();
            guards.Clear();
            if (!claimed && crate != null && !crate.IsDestroyed)
            {
                crate.Kill();
                Broadcast("Expired");
            }
            crate = null;
        }`,
