        private class Quest
        {
            public string Title;
            public string Objective;
            public string Target;
            public int Amount;
            public string Reward;
            public int RewardAmount;
        }

        private class Progress
        {
            public int Stage;
            public int Count;
        }

        private static List<Quest> DefaultQuests() => new List<Quest>
        {
            ${quests.map((q) => `new Quest { Title = ${JSON.stringify(q.Title)}, Objective = "${q.Objective}", Target = "${q.Target}", Amount = ${q.Amount}, Reward = "${q.Reward}", RewardAmount = ${q.RewardAmount} },`)}
        };

        private void Advance(BasePlayer player, string objective, string target, int amount)
        {
            if (player == null || player.IsNpc || target == null || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
            Progress state;
            if (!progress.TryGetValue(player.userID.Get(), out state)) progress[player.userID.Get()] = state = new Progress();
            if (state.Stage >= quests.Count) return;
            var quest = quests[state.Stage];
            if (quest.Objective != objective || !target.Contains(quest.Target)) return;

            state.Count += amount;
            if (state.Count < quest.Amount)
            {
                if (objective != "Gather") Reply(player, "Progress", quest.Title, state.Count, quest.Amount);
                return;
            }
            var reward = ItemManager.CreateByName(quest.Reward, quest.RewardAmount);
            if (reward != null) player.GiveItem(reward);
            EffectNetwork.Send(new Effect(FxSuccess, player, 0, Vector3.zero, Vector3.zero), player.net.connection);
            state.Stage++;
            state.Count = 0;
            if (state.Stage < quests.Count) Reply(player, "StageDone", quest.Title, quests[state.Stage].Title);
            else Broadcast("Champion", player.displayName);
        }

        private void ShowJournal(BasePlayer player)
        {
            if (player == null || !player.IsConnected || quests.Count == 0) return;
            Progress state;
            progress.TryGetValue(player.userID.Get(), out state);
            var stage = state?.Stage ?? 0;
            if (stage >= quests.Count)
            {
                Reply(player, "AllDone");
                return;
            }
            var quest = quests[stage];
            Reply(player, "Journal", stage + 1, quests.Count, quest.Title, quest.Objective.ToLower(), quest.Amount, quest.Target, state?.Count ?? 0);
        }`,
      opts: [],
      msgs: {
        Journal: `<color=${acc}>Quest {0}/{1}: {2}</color>. {3} {4} × {5} ({6} so far).`,
        Progress: "{0}: {1}/{2}",
        StageDone: `<color=${acc}>{0}</color> complete! Next: {1}.`,
        Champion: `{0} completed <color=${acc}>${title}</color>!`,
        AllDone: "You've finished every quest. Legend.",
        Reset: "Quest progress reset.",
      },
      api: code`
        private int API_GetStage(ulong userId)
        {
            Progress state;
            return progress.TryGetValue(userId, out state) ? state.Stage : 0;
        }`,
      check: `Check(failures, "API_GetStage answers", ${cls}.Call("API_GetStage", 0UL) is int);`,
      extra: [file(`data/${cls}/Quests.json`, JSON.stringify(quests, null, 2) + "\n")],
    };
  } else if (k === "interface") {
    m = {
      label: "HUD",
      desc: `${title}: a toggleable team HUD with grid position, time of day and teammate health bars`,
      ...prefs,
      start: ["foreach (var player in BasePlayer.activePlayerList) DrawHud(player);", "timer.Every(config.RefreshSeconds, () => { foreach (var player in BasePlayer.activePlayerList) DrawHud(player); });"],
      hooks: join(
        snapshotWait("DrawHud(player);"),
        code`
          private void OnPlayerRespawned(BasePlayer player) => DrawHud(player);

          private void OnPlayerDeath(BasePlayer player, HitInfo info) => CuiHelper.DestroyUi(player, UiRoot);`,
      ),
      commands: toggle("DrawHud(player);"),
      logic: code`
        private void DrawHud(BasePlayer player)
        {
            if (player == null || !player.IsConnected) return;
            CuiHelper.DestroyUi(player, UiRoot);
            if (player.IsDead() || optedOut.Contains(player.userID.Get()) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;

            var ui = new CuiElementContainer();
            var root = ui.Add(new CuiPanel { Image = { Color = config.Background }, RectTransform = { AnchorMin = config.AnchorMin, AnchorMax = config.AnchorMax } }, "Hud", UiRoot);
            var header = Lang("Header", player.UserIDString, PhoneController.PositionToGridName(player.transform.position), TOD_Sky.Instance.Cycle.DateTime.ToString("HH:mm"));
            ui.Add(new CuiLabel { Text = { Text = header, FontSize = 11, Align = TextAnchor.MiddleLeft, Color = config.Accent, Font = "robotocondensed-bold.ttf" }, RectTransform = { AnchorMin = "0.05 0.8", AnchorMax = "0.95 0.97" } }, root);

            var row = 0;
            foreach (var id in player.Team != null ? player.Team.members : new List<ulong> { player.userID.Get() })
            {
                var mate = BasePlayer.FindByID(id) ?? BasePlayer.FindSleeping(id);
                if (mate == null || row >= config.MaxRows) continue;
                var top = 0.78f - row++ * (0.74f / config.MaxRows);
                var bottom = top - 0.7f / config.MaxRows;
                var health = mate.IsDead() ? 0f : mate.health / mate.MaxHealth();
                ui.Add(new CuiLabel { Text = { Text = mate.displayName, FontSize = 10, Align = TextAnchor.MiddleLeft, Color = mate.IsConnected ? "1 1 1 0.9" : "1 1 1 0.4" }, RectTransform = { AnchorMin = $"0.05 {bottom:0.000}", AnchorMax = $"0.5 {top:0.000}" } }, root);
                var bar = ui.Add(new CuiPanel { Image = { Color = "1 1 1 0.08" }, RectTransform = { AnchorMin = $"0.52 {bottom + 0.02f:0.000}", AnchorMax = $"0.95 {top - 0.02f:0.000}" } }, root);
                ui.Add(new CuiPanel { Image = { Color = health < 0.3f ? "0.9 0.25 0.2 0.9" : config.Accent }, RectTransform = { AnchorMin = "0 0", AnchorMax = $"{health:0.00} 1" } }, bar);
            }
            CuiHelper.AddUi(player, ui);
        }`,
      opts: [
        opt("Refresh interval (seconds)", "RefreshSeconds", Math.max(2, n.interval)),
        opt("Anchor min", "AnchorMin", "0.005 0.72"),
        opt("Anchor max", "AnchorMax", "0.17 0.92"),
        opt("Background color", "Background", "0.08 0.08 0.1 0.72"),
        opt("Accent color", "Accent", `${fxs[0].tint.map((c) => c.toFixed(2)).join(" ")} 1`),
        opt("Max teammate rows", "MaxRows", 6, "int"),
      ],
      msgs: { Header: `${title.toUpperCase()} · {0} · {1}`, On: `<color=${acc}>HUD on.</color>`, Off: `HUD hidden. Type /${cmd} to bring it back.` },
      api: "private bool API_IsHudVisible(BasePlayer player) => player != null && !optedOut.Contains(player.userID.Get());",
      check: `Check(failures, "API_IsHudVisible answers", ${cls}.Call("API_IsHudVisible", (BasePlayer)null) is bool);`,
    };
  } else if (k === "audio") {
    m = {
      label: "Sound Cues",
      desc: `${title}: hit, headshot and kill sound cues, a nightfall chime and day/night boombox stations`,
      ...prefs,
      fields: [...prefs.fields, "private bool wasNight;"],
      start: ["wasNight = TOD_Sky.Instance.IsNight;", "timer.Every(10f, CheckNightfall);"],
      hooks: code`
        private void OnPlayerAttack(BasePlayer attacker, HitInfo info)
        {
            if (attacker == null || attacker.IsNpc || info?.HitEntity == null || info.HitEntity is BuildingBlock || !Listening(attacker)) return;
            Play(attacker, info.isHeadshot ? config.HeadshotSound : config.HitSound);
        }

        private void OnEntityDeath(BasePlayer victim, HitInfo info)
        {
            var killer = info?.InitiatorPlayer;
            if (killer != null && killer != victim && Listening(killer)) Play(killer, config.KillSound);
        }`,
      commands: toggle(""),
      logic: code`
        private void CheckNightfall()
        {
            var night = TOD_Sky.Instance.IsNight;
            if (night == wasNight) return;
            wasNight = night;
            foreach (var player in BasePlayer.activePlayerList)
                if (Listening(player)) Play(player, night ? config.NightfallSound : config.DaybreakSound);

            if (!config.SwitchStations) return;
            foreach (var box in BaseNetworkable.serverEntities.OfType<DeployableBoomBox>())
            {
                box.BoxController.CurrentRadioIp = night ? config.NightStation : config.DayStation;
                box.BoxController.ServerTogglePlay(true);
                box.SendNetworkUpdate();
            }
        }

        private bool Listening(BasePlayer player) => player.IsConnected && !optedOut.Contains(player.userID.Get()) && permission.UserHasPermission(player.UserIDString, PermUse);

        private void Play(BasePlayer player, string prefab) => EffectNetwork.Send(new Effect(prefab, player, 0, Vector3.up, Vector3.zero), player.net.connection);`,
      opts: [
        opt("Hit sound", "HitSound", "assets/bundled/prefabs/fx/takedamage_hit.prefab"),
        opt("Headshot sound", "HeadshotSound", ASSETS.FxHeadshot),
        opt("Kill sound", "KillSound", "assets/prefabs/deployable/research table/effects/research-success.prefab"),
        opt("Nightfall sound", "NightfallSound", ASSETS.FxCast),
        opt("Daybreak sound", "DaybreakSound", ASSETS.FxAlarm),
        opt("Switch boombox stations at dusk/dawn", "SwitchStations", fxs.some((e) => e.key === "lunar")),
        opt("Day station URL", "DayStation", "http://radio.example.com:8000/day"),
        opt("Night station URL", "NightStation", "http://radio.example.com:8000/night"),
      ],
      msgs: { On: `<color=${acc}>${title}</color> sounds on.`, Off: `${title} sounds muted. Type /${cmd} to unmute.` },
      api: "private bool API_IsListening(BasePlayer player) => player != null && Listening(player);",
      check: `Check(failures, "API_IsListening answers", ${cls}.Call("API_IsListening", (BasePlayer)null) is bool);`,
    };
  } else {
    const night = fxs.some((e) => e.key === "lunar") || /night|moon|dark/.test(text);
    m = {
      label: "Color Grade",
      desc: `${title}: a server-side color grade through weather.atmosphere convars, plus an optional screen tint`,
      ...prefs,
      fields: [...prefs.fields, "private bool graded;"],
      start: ["timer.Every(config.CheckSeconds, Grade);", "Grade();"],
      unload: ["graded = false;", "ApplyWeather();"],
      hooks: snapshotWait("Tint(player);"),
      commands: toggle("Tint(player);"),
      logic: code`
        private void Grade()
        {
            var wanted = !config.NightOnly || TOD_Sky.Instance.IsNight;
            if (wanted == graded) return;
            graded = wanted;
            ApplyWeather();
            foreach (var player in BasePlayer.activePlayerList) Tint(player);
        }

        // -1 hands each convar back to Rust's own weather.
        private void ApplyWeather()
        {
            SetWeather("atmosphere_brightness", graded ? config.Brightness : -1f);
            SetWeather("atmosphere_contrast", graded ? config.Contrast : -1f);
            SetWeather("atmosphere_rayleigh", graded ? config.Rayleigh : -1f);
            SetWeather("atmosphere_mie", graded ? config.Mie : -1f);
            SetWeather("fog", graded ? config.Fog : -1f);
        }

        private static void SetWeather(string convar, float value) => ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), "weather." + convar, value);

        private void Tint(BasePlayer player)
        {
            if (player == null || !player.IsConnected) return;
            CuiHelper.DestroyUi(player, UiTint);
            if (!graded || optedOut.Contains(player.userID.Get()) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
            var ui = new CuiElementContainer();
            ui.Add(new CuiPanel { Image = { Color = config.Tint }, RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" } }, "Under", UiTint);
            CuiHelper.AddUi(player, ui);
        }`,
      opts: [
        opt("Only grade at night", "NightOnly", night),
        opt("Check interval (seconds)", "CheckSeconds", 15),
        opt("Atmosphere brightness", "Brightness", n.intensity),
        opt("Atmosphere contrast", "Contrast", r2(0.8 + n.intensity * 0.3)),
        opt("Atmosphere rayleigh", "Rayleigh", r2(n.intensity * 1.6)),
        opt("Atmosphere mie", "Mie", r2(0.5 + n.chance * 2)),
        opt("Fog (0-1)", "Fog", r2(n.chance / 2)),
        opt("Screen tint (r g b a)", "Tint", `${fxs[0].tint.map((c) => c.toFixed(2)).join(" ")} ${r2(n.intensity * 0.05)}`),
      ],
      msgs: { On: `<color=${acc}>${title}</color> tint on.`, Off: `${title} tint off. Type /${cmd} to turn it back on.` },
      api: "private bool API_IsGraded() => graded;",
      check: `Check(failures, "API_IsGraded answers", ${cls}.Call("API_IsGraded") is bool);`,
    };
  }

  /* ───── assemble: effects, helpers and consts are only emitted when the plugin references them ───── */
  const usesFx = /\bApplyEffects\(/.test(join(m.hooks, m.commands, m.logic, ...(m.start ?? [])));
  const own = join(m.hooks, m.logic);
  const fx = usesFx ? fxs.map((e) => FX[e.key]) : [];
  const applies = fx.map((f) => f.apply).join("\n\n");
  const members = fx.map((f) => f.member).filter((s): s is string => !!s && !own.includes(s.match(/void (\w+)\(/)![1] + "("));
  const effects =
    usesFx &&
    code`
      private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)
      {
          if (applying || (attacker == null && target == null)) return;
          applying = true;
          try
          {
              ${/\bcaster\b/.test(applies) ? "var caster = attacker as BasePlayer;" : ""}
              ${/\bvictim\b/.test(applies) ? "var victim = target as BasePlayer;" : ""}
              ${/\bpos\b/.test(applies) ? "var pos = (target ?? attacker).transform.position;" : ""}

              ${applies}
          }
          finally
          {
              applying = false;
          }
      }

      ${members.join("\n\n")}`;

  const helpers: { re: RegExp; field?: string; body: string }[] = [
    {
      re: /\bOnCooldown\(/,
      field: "private readonly Dictionary<ulong, float> cooldowns = new Dictionary<ulong, float>();",
      body: code`
        private bool OnCooldown(BasePlayer player, bool notify = false)
        {
            float readyAt;
            var now = Time.realtimeSinceStartup;
            if (cooldowns.TryGetValue(player.userID.Get(), out readyAt) && readyAt > now)
            {
                if (notify) Reply(player, "Cooldown", readyAt - now);
                return true;
            }
            cooldowns[player.userID.Get()] = now + config.Cooldown;
            return false;
        }`,
    },
    {
      re: /\bsummonOwners\b/,
      field: "private readonly Dictionary<ulong, ulong> summonOwners = new Dictionary<ulong, ulong>();",
      body: code`
        // Keeps summoned NPCs off their owner and the owner's allies.
        private object OnNpcTarget(BaseEntity npc, BaseEntity target)
        {
            ulong ownerId;
            var player = target as BasePlayer;
            if (npc?.net == null || player == null || !summonOwners.TryGetValue(npc.net.ID.Value, out ownerId)) return null;
            if (player.userID.Get() != ownerId && !IsAlly(BasePlayer.FindByID(ownerId), player)) return null;
            return true;
        }`,
    },
    {
      re: /\bIsAlly\(/,
      field: deep ? "[PluginReference] private Plugin Clans, Friends;" : undefined,
      body: code`
        private bool IsAlly(BasePlayer a, BasePlayer b)
        {
            if (a == null || b == null) return false;
            if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
            ${deep ? 'if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;\nreturn Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);' : "return false;"}
        }`,
    },
    {
      re: /\bIsTeammate\(/,
      body: code`
        private static bool IsTeammate(ulong ownerId, BasePlayer player)
        {
            var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
            return player != null && team != null && team.members.Contains(player.userID.Get());
        }`,
    },
    {
      re: /\bDamage\(/,
      body: code`
        private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
        {
            if (info != null) info.damageTypes.Add(type, amount);
            else target.Hurt(amount, type, attacker);
        }`,
    },
    { re: /\bReply\(/, body: 'private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");' },
    { re: /\bBroadcast\(/, body: 'private void Broadcast(string key, params object[] args) => PrintToChat($"{config.ChatPrefix} {Lang(key, null, args)}");' },
    { re: /./, body: "private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);" },
  ];
  const api = rich ? m.api : "";
  let scan = join(own, m.commands, effects, api, ...(m.init ?? []), ...(m.start ?? []), ...(m.unload ?? []));
  const used = new Set<number>();
  for (let pass = 0; pass < 3; pass++) helpers.forEach((h, i) => h.re.test(scan) && !used.has(i) && (used.add(i), (scan += "\n" + h.body)));
  const helperList = helpers.filter((_, i) => used.has(i));

  const consts = [
    `private const string PermUse = "${lc}.use";`,
    /\bPermAdmin\b/.test(scan) && `private const string PermAdmin = "${lc}.admin";`,
    ...Object.entries(ASSETS).filter(([name]) => new RegExp(`\\b${name}\\b`).test(scan)).map(([name, path]) => `private const string ${name} = "${path}";`),
    ...[...new Set(scan.match(/\bUi[A-Z]\w*/g) ?? [])].map((ui) => `private const string ${ui} = "${cls}.${ui.slice(2)}";`),
  ];
  const uiNames = [...new Set(scan.match(/\bUi[A-Z]\w*/g) ?? [])];
  const fields = [
    consts,
    "",
    "private Configuration config;",
    ...(m.fields ?? []),
    ...helperList.map((h) => h.field),
    usesFx && "private bool applying;",
  ];
  const lifecycle = code`
    private void Init()
    {
        permission.RegisterPermission(PermUse, this);
        ${/\bPermAdmin\b/.test(scan) ? "permission.RegisterPermission(PermAdmin, this);" : ""}
        ${m.init ?? []}
    }

    ${m.start ? `private void OnServerInitialized()\n{\n${m.start.map((l) => l.replace(/^/gm, "    ")).join("\n")}\n}` : ""}

    ${m.save ? `private void OnServerSave() => SaveData();\n\nprivate void SaveData()\n{\n${m.save.map((l) => "    " + l).join("\n")}\n}` : ""}

    ${
      m.unload || m.save || uiNames.length
        ? `private void Unload()\n{\n${[
            ...(m.unload ?? []),
            ...(uiNames.length ? [`foreach (var player in BasePlayer.activePlayerList)\n{\n${uiNames.map((u) => `    CuiHelper.DestroyUi(player, ${u});`).join("\n")}\n}`] : []),
            ...(m.save ? ["SaveData();"] : []),
          ]
            .map((l) => l.replace(/^/gm, "    "))
            .join("\n")}\n}`
        : ""
    }`;
  scan += lifecycle;

  // Config entries and messages the plugin actually reads.
  const optPool = [
    opt("Chat prefix", "ChatPrefix", `<color=${acc}>[${title}]</color>`),
    ...m.opts,
    opt("Cooldown (seconds)", "Cooldown", n.cooldown),
    opt("Effect power", "EffectPower", n.power),
    opt("Effect duration (seconds)", "EffectSeconds", n.duration),
    opt("Effect radius (meters)", "EffectRadius", n.radius),
    ...fx.flatMap((f) => f.opts?.(n) ?? []),
  ];
  const opts = optPool.filter((o, i) => optPool.findIndex((p) => p.name === o.name) === i && scan.includes(`config.${o.name}`));
  const msgPool: Record<string, string> = {
    NoPermission: "You don't have permission to use this.",
    PlayerNotFound: "No player found matching '{0}'.",
    Cooldown: "Recharging, {0:0.0}s left.",
    ...m.msgs,
    ...Object.assign({}, ...fx.map((f) => f.msgs ?? {})),
  };
  const msgs = Object.fromEntries(Object.entries(msgPool).filter(([key]) => scan.includes(`"${key}"`) || key in m.msgs));

  const usings = [
    "using System;",
    "using System.Collections.Generic;",
    "using System.Linq;",
    "using Newtonsoft.Json;",
    "using Oxide.Core;",
    /PluginReference/.test(scan) && "using Oxide.Core.Plugins;",
    /\bCui[A-Z]/.test(scan) && "using Oxide.Game.Rust.Cui;",
    /\b(DamageType|Layers)\./.test(scan) && "using Rust;",
    "using UnityEngine;",
    /\bRandom\./.test(scan) && "using Random = UnityEngine.Random;",
  ];

  const main = file(
    `plugins/${cls}.cs`,
    code`
      // ${title}: ${input.category.label.toLowerCase()} plugin for Rust, forged by Cyrus (${model}) v${input.version}.
      // Runs on Oxide/uMod and Carbon. Drop it into oxide/plugins (or carbon/plugins); it compiles on load.
      ${input.version > 1 ? `// v${input.version}: retuned numbers; every value lives in config/${cls}.json.` : ""}
      ${usings}

      namespace Oxide.Plugins
      {
          [Info("${title}", "Cyrus", "${input.version}.0.0")]
          [Description("${m.desc.replace(/"/g, "'")}")]
          public class ${cls} : RustPlugin
          {
              ${join(
                region("Fields", fields.filter((f) => f !== false && f !== undefined).flat().join("\n")),
                region("Oxide Hooks", join(lifecycle, m.hooks)),
                region("Commands", m.commands),
                region(m.label, m.logic ?? ""),
                region("Effects", effects || ""),
                region("API", api),
                region("Helpers", helperList.map((h) => h.body).join("\n\n")),
                region(
                  "Configuration",
                  code`
                    private class Configuration
                    {
                        ${opts.map((o) => `[JsonProperty(${JSON.stringify(o.key)})]\npublic ${csType(o)} ${o.name} = ${csValue(o)};`).join("\n\n")}
                    }

                    protected override void LoadConfig()
                    {
                        base.LoadConfig();
                        try
                        {
                            config = Config.ReadObject<Configuration>();
                            if (config == null) throw new JsonException();
                            SaveConfig();
                        }
                        catch (Exception ex)
                        {
                            PrintError($"Config file is invalid ({ex.Message}); using defaults.");
                            LoadDefaultConfig();
                        }
                    }

                    protected override void LoadDefaultConfig() => config = new Configuration();

                    protected override void SaveConfig() => Config.WriteObject(config, true);`,
                ),
                region(
                  "Localization",
                  code`
                    protected override void LoadDefaultMessages()
                    {
                        lang.RegisterMessages(new Dictionary<string, string>
                        {
                            ${Object.entries(msgs).map(([key, v]) => `[${JSON.stringify(key)}] = ${JSON.stringify(v)},`)}
                        }, this);
                    }`,
                ),
              )}
          }
      }`,
  );

  const config = file(`config/${cls}.json`, `{\n${opts.map((o) => `  ${JSON.stringify(o.key)}: ${jsonValue(o).replace(/\n/g, "\n  ")}`).join(",\n")}\n}\n`);
  const l10n = file(`lang/en/${cls}.json`, JSON.stringify(msgs, null, 2) + "\n");
  const test = file(
    `tests/${cls}SelfTest.cs`,
    code`
      // Self-test harness for ${title}. Copy it next to ${cls}.cs in oxide/plugins, then run
      // \`${cmd}.selftest\` from the server console or RCON. Unload it again on live servers.
      using System.Collections.Generic;
      using Oxide.Core.Plugins;

      namespace Oxide.Plugins
      {
          [Info("${title} Self Test", "Cyrus", "${input.version}.0.0")]
          [Description("Checks that ${title} loaded with its permissions, messages and API")]
          public class ${cls}SelfTest : RustPlugin
          {
              [PluginReference] private Plugin ${cls};

              [ConsoleCommand("${cmd}.selftest")]
              private void CcmdSelfTest(ConsoleSystem.Arg arg)
              {
                  if (!arg.IsAdmin) return;
                  if (${cls} == null || !${cls}.IsLoaded)
                  {
                      arg.ReplyWith("${title} is not loaded");
                      return;
                  }

                  var failures = new List<string>();
                  Check(failures, "permission ${lc}.use is registered", permission.PermissionExists("${lc}.use", ${cls}));
                  foreach (var key in new[] { ${Object.keys(msgs).slice(0, 4).map((key) => JSON.stringify(key)).join(", ")} })
                      Check(failures, $"message '{key}' is registered", lang.GetMessage(key, ${cls}) != key);
                  ${m.check}

                  arg.ReplyWith(failures.Count == 0 ? "${title}: all checks passed" : $"${title}: {failures.Count} failed\\n- " + string.Join("\\n- ", failures));
              }

              private static void Check(List<string> failures, string name, bool passed)
              {
                  if (!passed) failures.Add(name);
              }
          }
      }`,
  );

  return { files: [main, ...(m.extra ?? [])], config, l10n, test };
}

