        `quests = Interface.Oxide.DataFileSystem.ReadObject<List<Quest>>($"{Name}/Quests");`,
        `if (quests == null || quests.Count == 0) Interface.Oxide.DataFileSystem.WriteObject($"{Name}/Quests", quests = DefaultQuests());`,
