        private void OnDispenserGather(ResourceDispenser dispenser, BaseEntity entity, Item item) => Advance(entity?.ToPlayer(), "Gather", item.info.shortname, item.amount);

        private void OnEntityDeath(BaseCombatEntity entity, HitInfo info) => Advance(info?.InitiatorPlayer, "Kill", entity?.ShortPrefabName, 1);

