        {
            if (entity is LootContainer && entity.net != null && looted.Add(entity.net.ID.Value)) Advance(player, "Loot", entity.ShortPrefabName, 1);
        }

        private void OnPlayerConnected(BasePlayer player) => timer.Once(5f, () => ShowJournal(player));`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdQuest(BasePlayer player, string command, string[] args)
        {
            if (args.Length > 0 && args[0] == "reset" && permission.UserHasPermission(player.UserIDString, PermAdmin))
            {
