      logic: code`
        private class Quest
        {
            public string Title;
            public string Objective;
            public string Target;
            public int Amount;
            public string Reward;
            public int RewardAmount;
        }

        private class Progress
        {
            public int Stage;
            public int Count;
        }

        private static List<Quest> DefaultQuests() => new List<Quest>
        {
            ${quests.map((q) => `new Quest { Title = ${JSON.stringify(q.Title)}, Objective = "${q.Objective}", Target = "${q.Target}", Amount = ${q.Amount}, Reward = "${q.Reward}", RewardAmount = ${q.RewardAmount} },`)}
        };

        private void Advance(BasePlayer player, string objective, string target, int amount)
        {
            if (player == null || player.IsNpc || target == null || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
            Progress state;
            if (!progress.TryGetValue(player.userID.Get(), out state)) progress[player.userID.Get()] = state = new Progress();
            if (state.Stage >= quests.Count) return;
            var quest = quests[state.Stage];
            if (quest.Objective != objective || !target.Contains(quest.Target)) return;

            state.Count += amount;
            if (state.Count < quest.Amount)
            {
                if (objective != "Gather") Reply(player, "Progress", quest.Title, state.Count, quest.Amount);
                return;
            }
            var reward = ItemManager.CreateByName(quest.Reward, quest.RewardAmount);
            if (reward != null) player.GiveItem(reward);
            EffectNetwork.Send(new Effect(FxSuccess, player, 0, Vector3.zero, Vector3.zero), player.net.connection);
            state.Stage++;
            state.Count = 0;
            if (state.Stage < quests.Count) Reply(player, "StageDone", quest.Title, quests[state.Stage].Title);
            else Broadcast("Champion", player.displayName);
        }

        private void ShowJournal(BasePlayer player)
        {
            if (player == null || !player.IsConnected || quests.Count == 0) return;
            Progress state;
            progress.TryGetValue(player.userID.Get(), out state);
            var stage = state?.Stage ?? 0;
            if (stage >= quests.Count)
            {
                Reply(player, "AllDone");
                return;
            }
            var quest = quests[stage];
            Reply(player, "Journal", stage + 1, quests.Count, quest.Title, quest.Objective.ToLower(), quest.Amount, quest.Target, state?.Count ?? 0);
        }`,
