        private void DrawHud(BasePlayer player)
        {
            if (player == null || !player.IsConnected) return;
            CuiHelper.DestroyUi(player, UiRoot);
            if (player.IsDead() || optedOut.Contains(player.userID.Get()) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;

            var ui = new CuiElementContainer();
            var root = ui.Add(new CuiPanel { Image = { Color = config.Background }, RectTransform = { AnchorMin = config.AnchorMin, AnchorMax = config.AnchorMax } }, "Hud", UiRoot);
            var header = Lang("Header", player.UserIDString, PhoneController.PositionToGridName(player.transform.position), TOD_Sky.Instance.Cycle.DateTime.ToString("HH:mm"));
            ui.Add(new CuiLabel { Text = { Text = header, FontSize = 11, Align = TextAnchor.MiddleLeft, Color = config.Accent, Font = "robotocondensed-bold.ttf" }, RectTransform = { AnchorMin = "0.05 0.8", AnchorMax = "0.95 0.97" } }, root);

            var row = 0;
            foreach (var id in player.Team != null ? player.Team.members : new List<ulong> { player.userID.Get() })
            {
                var mate = BasePlayer.FindByID(id) ?? BasePlayer.FindSleeping(id);
                if (mate == null || row >= config.MaxRows) continue;
                var top = 0.78f - row++ * (0.74f / config.MaxRows);
                var bottom = top - 0.7f / config.MaxRows;
                var health = mate.IsDead() ? 0f : mate.health / mate.MaxHealth();
                ui.Add(new CuiLabel { Text = { Text = mate.displayName, FontSize = 10, Align = TextAnchor.MiddleLeft, Color = mate.IsConnected ? "1 1 1 0.9" : "1 1 1 0.4" }, RectTransform = { AnchorMin = $"0.05 {bottom:0.000}", AnchorMax = $"0.5 {top:0.000}" } }, root);
                var bar = ui.Add(new CuiPanel { Image = { Color = "1 1 1 0.08" }, RectTransform = { AnchorMin = $"0.52 {bottom + 0.02f:0.000}", AnchorMax = $"0.95 {top - 0.02f:0.000}" } }, root);
                ui.Add(new CuiPanel { Image = { Color = health < 0.3f ? "0.9 0.25 0.2 0.9" : config.Accent }, RectTransform = { AnchorMin = "0 0", AnchorMax = $"{health:0.00} 1" } }, bar);
            }
            CuiHelper.AddUi(player, ui);
        }`,
