  const msgPool: Record<string, string> = {
    NoPermission: "You don't have permission to use this.",
    PlayerNotFound: "No player found matching '{0}'.",
    Cooldown: "Recharging, {0:0.0}s left.",
    ...m.msgs,
    ...Object.assign({}, ...fx.map((f) => f.msgs ?? {})),
  };
  const msgs = Object.fromEntries(Object.entries(msgPool).filter(([key]) => scan.includes(`"${key}"`) || key in m.msgs));

  const usings = [
    "using System;",
    "using System.Collections.Generic;",
    "using System.Linq;",
    "using Newtonsoft.Json;",
    "using Oxide.Core;",
    /PluginReference/.test(scan) && "using Oxide.Core.Plugins;",
    /\bCui[A-Z]/.test(scan) && "using Oxide.Game.Rust.Cui;",
    /\b(DamageType|Layers)\./.test(scan) && "using Rust;",
    "using UnityEngine;",
    /\bRandom\./.test(scan) && "using Random = UnityEngine.Random;",
  ];

  const main = file(
    `plugins/${cls}.cs`,
    code`
      // ${title}: ${input.category.label.toLowerCase()} plugin for Rust, forged by Cyrus (${model}) v${input.version}.
      // Runs on Oxide/uMod and Carbon. Drop it into oxide/plugins (or carbon/plugins); it compiles on load.
      ${input.version > 1 ? `// v${input.version}: retuned numbers; every value lives in config/${cls}.json.` : ""}
      ${usings}

      namespace Oxide.Plugins
      {
          [Info("${title}", "Cyrus", "${input.version}.0.0")]
          [Description("${m.desc.replace(/"/g, "'")}")]
          public class ${cls} : RustPlugin
          {
              ${join(
                region("Fields", fields.filter((f) => f !== false && f !== undefined).flat().join("\n")),
                region("Oxide Hooks", join(lifecycle, m.hooks)),
                region("Commands", m.commands),
                region(m.label, m.logic ?? ""),
                region("Effects", effects || ""),
                region("API", api),
                region("Helpers", helperList.map((h) => h.body).join("\n\n")),
                region(
                  "Configuration",
                  code`
                    private class Configuration
                    {
                        ${opts.map((o) => `[JsonProperty(${JSON.stringify(o.key)})]\npublic ${csType(o)} ${o.name} = ${csValue(o)};`).join("\n\n")}
                    }

                    protected override void LoadConfig()
                    {
                        base.LoadConfig();
                        try
                        {
                            config = Config.ReadObject<Configuration>();
                            if (config == null) throw new JsonException();
                            SaveConfig();
                        }
                        catch (Exception ex)
                        {
                            PrintError($"Config file is invalid ({ex.Message}); using defaults.");
                            LoadDefaultConfig();
                        }
                    }

                    protected override void LoadDefaultConfig() => config = new Configuration();

                    protected override void SaveConfig() => Config.WriteObject(config, true);`,
                ),
                region(
                  "Localization",
                  code`
                    protected override void LoadDefaultMessages()
                    {
                        lang.RegisterMessages(new Dictionary<string, string>
                        {
                            ${Object.entries(msgs).map(([key, v]) => `[${JSON.stringify(key)}] = ${JSON.stringify(v)},`)}
                        }, this);
                    }`,
                ),
              )}
          }
      }`,
  );

  const config = file(`config/${cls}.json`, `{\n${opts.map((o) => `  ${JSON.stringify(o.key)}: ${jsonValue(o).replace(/\n/g, "\n  ")}`).join(",\n")}\n}\n`);
  const l10n = file(`lang/en/${cls}.json`, JSON.stringify(msgs, null, 2) + "\n");
  const test = file(
    `tests/${cls}SelfTest.cs`,
    code`
      // Self-test harness for ${title}. Copy it next to ${cls}.cs in oxide/plugins, then run
      // \`${cmd}.selftest\` from the server console or RCON. Unload it again on live servers.
      using System.Collections.Generic;
      using Oxide.Core.Plugins;

      namespace Oxide.Plugins
      {
          [Info("${title} Self Test", "Cyrus", "${input.version}.0.0")]
          [Description("Checks that ${title} loaded with its permissions, messages and API")]
          public class ${cls}SelfTest : RustPlugin
          {
              [PluginReference] private Plugin ${cls};

              [ConsoleCommand("${cmd}.selftest")]
              private void CcmdSelfTest(ConsoleSystem.Arg arg)
              {
                  if (!arg.IsAdmin) return;
                  if (${cls} == null || !${cls}.IsLoaded)
                  {
                      arg.ReplyWith("${title} is not loaded");
                      return;
                  }

                  var failures = new List<string>();
                  Check(failures, "permission ${lc}.use is registered", permission.PermissionExists("${lc}.use", ${cls}));
                  foreach (var key in new[] { ${Object.keys(msgs).slice(0, 4).map((key) => JSON.stringify(key)).join(", ")} })
                      Check(failures, $"message '{key}' is registered", lang.GetMessage(key, ${cls}) != key);
                  ${m.check}

                  arg.ReplyWith(failures.Count == 0 ? "${title}: all checks passed" : $"${title}: {failures.Count} failed\\n- " + string.Join("\\n- ", failures));
              }

              private static void Check(List<string> failures, string name, bool passed)
              {
                  if (!passed) failures.Add(name);
              }
          }
      }`,
  );

  return { files: [main, ...(m.extra ?? [])], config, l10n, test };
}

