const prompts = {
  weapons: ["a railgun that pierces walls", "frost katana", "poison crossbow that summons minions"],
  creatures: ["a mutant bear boss", "shadow wolf pack"],
  worlds: ["a monument event", "frozen island biome"],
  mechanics: ["Smart raid alarms that ping your team and log the attacker", "auto harvest gather boost"],
  shaders: ["moonlit fog shader", "neon color grade"],
  magic: ["lightning staff spell", "blink rune that teleports"],
  quests: ["a questline into the dark"],
  interface: ["team hud overlay"],
  audio: ["night music and hit sounds"],
  vehicles: ["a minicopter with nitro boost", "flying car"],
  items: ["healing syringe relic", "auto pickaxe"],
  characters: ["a companion bodyguard"],
};
let problems = 0;
const lens = [];
for (const [cat, ps] of Object.entries(prompts)) {
  for (const prompt of ps) {
    for (const model of ["katara", "sokka", "yako"]) {
      for (const version of [1, 2]) {
        const modName = eng.deriveModName(prompt, rust, cat);
        const files = eng.buildModFiles({ game: rust, category: data.CATEGORY_BY_KEY[cat], modName, prompt, model, version });
        const main = files[0].content;
        lens.push(main.split("\n").length);
        const tag = `${cat}/${model}/v${version} "${prompt}"`;
        const err = (m) => { problems++; console.log(`!! ${tag}: ${m}`); };
        const cfgFields = new Set([...main.matchAll(/public \S+(?: \S+)? (\w+) = /g)].map((x) => x[1]));
        for (const [, name] of main.matchAll(/config\.(\w+)/g)) if (!cfgFields.has(name)) err(`config.${name} not declared`);
        const registered = new Set([...main.matchAll(/\["(\w+)"\] = "/g)].map((x) => x[1]));
        for (const [, key] of main.matchAll(/(?:Reply\(\w+, |Broadcast\(|Lang\()"(\w+)"/g)) if (!registered.has(key)) err(`lang key ${key} not registered`);
        for (const [, c] of main.matchAll(/\b((?:Fx|Prefab|Ui|Perm)[A-Z]\w*)\b/g)) if (!new RegExp(`const string ${c} =`).test(main)) err(`const ${c} missing`);
        const open = (main.match(/\{/g) || []).length, close = (main.match(/\}/g) || []).length;
        if (open !== close) err(`brace mismatch ${open}/${close}`);
        const paren = (main.match(/\(/g) || []).length - (main.match(/\)/g) || []).length;
        if (paren) err(`paren mismatch ${paren}`);
        const methods = [...main.matchAll(/^\s+(?:private|protected|public)[^=(\n]*? (\w+)\(/gm)].map((x) => x[1]);
        const dup = methods.filter((x, i) => methods.indexOf(x) !== i && !["Configuration"].includes(x));
        if (dup.length) err(`duplicate methods ${dup}`);
        for (const f of files.filter((f) => f.path.endsWith(".json"))) { try { JSON.parse(f.content); } catch (e) { err(`bad json ${f.path}`); } }
        if (/undefined|NaN|\[object/.test(files.map((f) => f.content).join())) err("undefined/NaN in output");
        if (/\n\n\n/.test(main)) err("triple newline");
        const helpers = ["OnCooldown", "IsAlly", "IsTeammate", "Damage", "Reply", "Broadcast", "Flash", "ApplyEffects"];
        for (const h of helpers) if (new RegExp(`\\b${h}\\(`).test(main) && !new RegExp(`(void|bool|object) ${h}\\(`).test(main)) err(`helper ${h} missing`);
      }
    }
  }
}
console.log(`problems: ${problems}; main.cs lines min ${Math.min(...lens)} max ${Math.max(...lens)}`);

