// Smart Raid Alarms: weapons plugin for Rust, forged by Cyrus (Yako) v1.
// Runs on Oxide/uMod and Carbon. Drop it into oxide/plugins (or carbon/plugins); it compiles on load.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Oxide.Core;
using Rust;
using UnityEngine;

namespace Oxide.Plugins
{
    [Info("Smart Raid Alarms", "Cyrus", "1.0.0")]
    [Description("Smart Raid Alarms: pings the base owner's team when their base is raided, logs the attacker and raid-blocks building")]
    public class SmartRaidAlarms : RustPlugin
    {
        #region Fields

        private const string PermUse = "smartraidalarms.use";
        false
        private const string FxShock = "assets/prefabs/locks/keypad/effects/lock.code.shock.prefab";
        private const string FxExplosion = "assets/bundled/prefabs/fx/explosions/explosion_03.prefab";
        private const string FxAlarm = "assets/bundled/prefabs/fx/invite_notice.prefab";

        private Configuration config;
        private StoredData data;
        private readonly Dictionary<ulong, float> lastAlert = new Dictionary<ulong, float>();
        private readonly Dictionary<ulong, float> raidBlocked = new Dictionary<ulong, float>();
        [PluginReference] private Plugin Clans, Friends;
        private bool applying;

        #endregion

        #region Oxide Hooks

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            data = Interface.Oxide.DataFileSystem.ReadObject<StoredData>(Name) ?? new StoredData();
        }

        private void OnServerSave() => SaveData();

        private void SaveData()
        {
            Interface.Oxide.DataFileSystem.WriteObject(Name, data);
        }

        private void Unload()
        {
            SaveData();
        }

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null || info == null || entity.OwnerID == 0UL || !(entity is DecayEntity)) return null;
            var attacker = info.InitiatorPlayer;
            if (attacker == null || attacker.IsNpc || attacker.userID.Get() == entity.OwnerID) return null;
            var priv = entity.GetBuildingPrivilege();
            if (priv == null || priv.IsAuthed(attacker) || IsTeammate(entity.OwnerID, attacker)) return null;
            if (!config.AlertOnMelee && !info.IsProjectile() && info.damageTypes.GetMajorityDamageType() != DamageType.Explosion) return null;

            raidBlocked[attacker.userID.Get()] = Time.realtimeSinceStartup + config.RaidBlockSeconds;
            Alert(priv, entity, attacker, info);
            if (config.PunishRaiders) ApplyEffects(null, attacker);
            return null;
        }

        private void OnEntityDeath(BuildingPrivlidge priv, HitInfo info)
        {
            var killer = info?.InitiatorPlayer;
            foreach (var member in OnlineTeam(priv.OwnerID))
                Reply(member, "CupboardLost", PhoneController.PositionToGridName(priv.transform.position), killer != null ? killer.displayName : "?");
        }

        private void OnCodeEntered(CodeLock codeLock, BasePlayer player, string code)
        {
            if (codeLock == null || player == null || code == codeLock.code || code == codeLock.guestCode) return;
            var owner = codeLock.GetParentEntity()?.OwnerID ?? codeLock.OwnerID;
            if (owner == player.userID.Get() || IsTeammate(owner, player)) return;
            foreach (var member in OnlineTeam(owner))
                Reply(member, "WrongCode", player.displayName, PhoneController.PositionToGridName(codeLock.transform.position));
        }

        private object CanBuild(Planner planner, Construction prefab, Construction.Target target) => RaidBlocked(planner?.GetOwnerPlayer());

        private object OnStructureUpgrade(BaseCombatEntity entity, BasePlayer player, BuildingGrade.Enum grade) => RaidBlocked(player);

        #endregion

        #region Commands

        [ChatCommand("raidalarms")]
        private void CmdRaidLog(BasePlayer player, string command, string[] args)
        {
            List<RaidEntry> log;
            if (!data.Logs.TryGetValue(player.userID.Get(), out log) || log.Count == 0)
            {
                Reply(player, "LogEmpty");
                return;
            }
            foreach (var entry in log.Take(5))
                Reply(player, "LogLine", entry.When.ToLocalTime().ToString("MM-dd HH:mm"), entry.Attacker, entry.Target, entry.Grid, entry.Weapon);
        }

        #endregion

        #region Raid Alarms

        private class StoredData
        {
            public Dictionary<ulong, List<RaidEntry>> Logs = new Dictionary<ulong, List<RaidEntry>>();
        }

        private class RaidEntry
        {
            public string Attacker;
            public ulong AttackerId;
            public string Target;
            public string Grid;
            public string Weapon;
            public DateTime When;
        }

        private void Alert(BuildingPrivlidge priv, BaseCombatEntity entity, BasePlayer attacker, HitInfo info)
        {
            float last;
            var now = Time.realtimeSinceStartup;
            if (lastAlert.TryGetValue(priv.net.ID.Value, out last) && now - last < config.AlertCooldown) return;
            lastAlert[priv.net.ID.Value] = now;

            var grid = PhoneController.PositionToGridName(entity.transform.position);
            var weapon = info.WeaponPrefab != null ? info.WeaponPrefab.ShortPrefabName : info.Weapon?.GetItem()?.info.shortname ?? "unknown";
            var entry = new RaidEntry { Attacker = attacker.displayName, AttackerId = attacker.userID.Get(), Target = entity.ShortPrefabName, Grid = grid, Weapon = weapon, When = DateTime.UtcNow };
            foreach (var member in OnlineTeam(entity.OwnerID))
            {
                Reply(member, "RaidAlert", attacker.displayName, entity.ShortPrefabName, grid, weapon);
                EffectNetwork.Send(new Effect(FxAlarm, member, 0, Vector3.zero, Vector3.zero), member.net.connection);
                if (Vector3.Distance(member.transform.position, entity.transform.position) < config.RaidBlockRadius)
                    raidBlocked[member.userID.Get()] = now + config.RaidBlockSeconds;
                List<RaidEntry> log;
                if (!data.Logs.TryGetValue(member.userID.Get(), out log)) data.Logs[member.userID.Get()] = log = new List<RaidEntry>();
                log.Insert(0, entry);
                if (log.Count > config.LogSize) log.RemoveRange(config.LogSize, log.Count - config.LogSize);
            }
            LogToFile("raids", $"{attacker.displayName} [{attacker.UserIDString}] hit {entity.ShortPrefabName} owned by {entity.OwnerID} at {grid} with {weapon}", this);
            Interface.CallHook("OnSmartRaidAlarmsAlert", priv, attacker, grid);
        }

        private IEnumerable<BasePlayer> OnlineTeam(ulong ownerId)
        {
            var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
            foreach (var id in team != null ? team.members : new List<ulong> { ownerId })
            {
                var member = BasePlayer.FindByID(id);
                if (member != null && permission.UserHasPermission(member.UserIDString, PermUse)) yield return member;
            }
        }

        private object RaidBlocked(BasePlayer player)
        {
            float until;
            if (player == null || !raidBlocked.TryGetValue(player.userID.Get(), out until) || until < Time.realtimeSinceStartup) return null;
            Reply(player, "RaidBlocked", until - Time.realtimeSinceStartup);
            return false;
        }

        #endregion

        #region Effects

        private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)
        {
            if (applying || (attacker == null && target == null)) return;
            applying = true;
            try
            {
                var caster = attacker as BasePlayer;
                var pos = (target ?? attacker).transform.position;

                // Storm: shock the target, then arc to anyone standing close by.
                if (target != null)
                {
                    Damage(target, attacker, info, DamageType.ElectricShock, config.EffectPower);
                    Effect.server.Run(FxShock, pos);
                    Effect.server.Run(FxExplosion, pos);
                    var arcs = new List<BasePlayer>();
                    Vis.Entities(pos, config.EffectRadius, arcs, Layers.Mask.Player_Server);
                    foreach (var other in arcs)
                    {
                        if (other == target || other == attacker || other.IsSleeping() || IsAlly(caster, other)) continue;
                        Effect.server.Run(FxShock, other.transform.position);
                        other.Hurt(config.EffectPower * 0.5f, DamageType.ElectricShock, attacker);
                    }
                }
            }
            finally
            {
                applying = false;
            }
        }

        #endregion

        #region API

        private int API_GetRaidCount(ulong userId)
        {
            List<RaidEntry> log;
            return data.Logs.TryGetValue(userId, out log) ? log.Count : 0;
        }

        #endregion

        #region Helpers

        private bool IsAlly(BasePlayer a, BasePlayer b)
        {
            if (a == null || b == null) return false;
            if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
            if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;
            return Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);
        }

        private static bool IsTeammate(ulong ownerId, BasePlayer player)
        {
            var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
            return player != null && team != null && team.members.Contains(player.userID.Get());
        }

        private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
        {
