// Self-test harness for Smart Raid Alarms. Copy it next to SmartRaidAlarms.cs in oxide/plugins, then run
// `raidalarms.selftest` from the server console or RCON. Unload it again on live servers.
using System.Collections.Generic;
using Oxide.Core.Plugins;

namespace Oxide.Plugins
{
    [Info("Smart Raid Alarms Self Test", "Cyrus", "1.0.0")]
    [Description("Checks that Smart Raid Alarms loaded with its permissions, messages and API")]
    public class SmartRaidAlarmsSelfTest : RustPlugin
    {
        [PluginReference] private Plugin SmartRaidAlarms;

        [ConsoleCommand("raidalarms.selftest")]
        private void CcmdSelfTest(ConsoleSystem.Arg arg)
        {
            if (!arg.IsAdmin) return;
            if (SmartRaidAlarms == null || !SmartRaidAlarms.IsLoaded)
            {
                arg.ReplyWith("Smart Raid Alarms is not loaded");
                return;
            }

            var failures = new List<string>();
            Check(failures, "permission smartraidalarms.use is registered", permission.PermissionExists("smartraidalarms.use", SmartRaidAlarms));
            foreach (var key in new[] { "RaidAlert", "CupboardLost", "WrongCode", "RaidBlocked" })
                Check(failures, $"message '{key}' is registered", lang.GetMessage(key, SmartRaidAlarms) != key);
            Check(failures, "API_GetRaidCount answers", SmartRaidAlarms.Call("API_GetRaidCount", 0UL) is int);

            arg.ReplyWith(failures.Count == 0 ? "Smart Raid Alarms: all checks passed" : $"Smart Raid Alarms: {failures.Count} failed\n- " + string.Join("\n- ", failures));
        }

        private static void Check(List<string> failures, string name, bool passed)
        {
            if (!passed) failures.Add(name);
        }
    }
}


