  /* ───── assembly: effects, helpers, consts, config entries and messages are emitted only when referenced ───── */
  const own = join(m.hooks, m.commands, m.logic, ...(m.start ?? []));
  const fx = /\bApplyEffects\(/.test(own) ? fxs.map((e) => FX[e.key]) : [];
  const applies = fx.map((f) => f.apply).join("\n\n");
  const locals = [["caster", "attacker as BasePlayer"], ["victim", "target as BasePlayer"], ["pos", "(target ?? attacker).transform.position"]].filter(([v]) => new RegExp(`\\b${v}\\b`).test(applies));
  const effects =
    fx.length > 0 &&
    join(
      block("private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)", [
        "if (applying || (attacker == null && target == null)) return;",
        "applying = true;",
        block("try", [locals.map(([v, e]) => `var ${v} = ${e};`).join("\n") + "\n\n" + applies]),
        block("finally", ["applying = false;"]),
      ]),
      ...fx.map((f) => f.member).filter((s) => s && !own.includes(s.match(/void (\w+\()/)![1])),
    );
  const helpers: [RegExp, string | undefined, string][] = [
    [/\bOnCooldown\(/, "private readonly Dictionary<ulong, float> cooldowns = new Dictionary<ulong, float>();", code`
      private bool OnCooldown(BasePlayer player, bool notify = false)
      {
          float readyAt;
          var now = Time.realtimeSinceStartup;
          if (cooldowns.TryGetValue(player.userID.Get(), out readyAt) && readyAt > now)
          {
              if (notify) Reply(player, "Cooldown", readyAt - now);
              return true;
          }
          cooldowns[player.userID.Get()] = now + config.Cooldown;
          return false;
      }`],
    [/\bsummonOwners\b/, "private readonly Dictionary<ulong, ulong> summonOwners = new Dictionary<ulong, ulong>();", code`
      // Keeps owned NPCs off their owner and the owner's allies.
      private object OnNpcTarget(BaseEntity npc, BaseEntity target)
      {
          ulong ownerId;
          var player = target as BasePlayer;
          if (npc?.net == null || player == null || !summonOwners.TryGetValue(npc.net.ID.Value, out ownerId)) return null;
          return player.userID.Get() == ownerId || IsAlly(BasePlayer.FindByID(ownerId), player) ? true : (object)null;
      }`],
    [/\bIsAlly\(/, deep ? "[PluginReference] private Plugin Clans, Friends;" : undefined, code`
      private bool IsAlly(BasePlayer a, BasePlayer b)
      {
          if (a == null || b == null) return false;
          if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
          ${deep ? 'if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;\nreturn Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);' : "return false;"}
      }`],
    [/\bIsTeammate\(/, undefined, code`
      private static bool IsTeammate(ulong ownerId, BasePlayer player)
      {
          var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
          return player != null && team != null && team.members.Contains(player.userID.Get());
      }`],
    [/\bDamage\(/, undefined, code`
      private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
      {
          if (info != null) info.damageTypes.Add(type, amount);
          else target.Hurt(amount, type, attacker);
      }`],
    [/\bReply\(/, undefined, 'private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");'],
    [/\bBroadcast\(/, undefined, 'private void Broadcast(string key, params object[] args) => PrintToChat($"{config.ChatPrefix} {Lang(key, null, args)}");'],
    [/./, undefined, "private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);"],
  ];
  const api = input.model !== "katara" ? m.api : "";
  let scan = join(own, effects, api, ...(m.init ?? []), ...(m.unload ?? []));
  const used = new Set<number>();
  for (let pass = 0; pass < 3; pass++) helpers.forEach(([re, , body], i) => !used.has(i) && re.test(scan) && (used.add(i), (scan += "\n" + body)));
  const helperList = helpers.filter((_, i) => used.has(i));
  const uis = [...new Set(scan.match(/\bUi[A-Z]\w*/g) ?? [])];
  const admin = /\bPermAdmin\b/.test(scan);
  const fields = [
    `private const string PermUse = "${lc}.use";`,
    admin && `private const string PermAdmin = "${lc}.admin";`,
    ...Object.entries(ASSETS).filter(([name]) => new RegExp(`\\b${name}\\b`).test(scan)).map(([name, path]) => `private const string ${name} = "${path}";`),
    ...uis.map((ui) => `private const string ${ui} = "${cls}.${ui.slice(2)}";`),
    "\nprivate Configuration config;",
    ...(m.fields ?? []),
    ...helperList.map(([, field]) => field),
    fx.length > 0 && "private bool applying;",
  ].filter(Boolean);
  const unload = [
    ...(m.unload ?? []),
    ...(uis.length ? [block("foreach (var player in BasePlayer.activePlayerList)", uis.map((ui) => `CuiHelper.DestroyUi(player, ${ui});`))] : []),
    ...(m.save ? ["SaveData();"] : []),
  ];
  const lifecycle = join(
    block("private void Init()", ["permission.RegisterPermission(PermUse, this);", ...(admin ? ["permission.RegisterPermission(PermAdmin, this);"] : []), ...(m.init ?? [])]),
    m.start && block("private void OnServerInitialized()", m.start),
    m.save && `private void OnServerSave() => SaveData();\n\n${block("private void SaveData()", m.save)}`,
    unload.length > 0 && block("private void Unload()", unload),
  );
  scan += lifecycle;

  const optPool = [
    opt("Chat prefix", "ChatPrefix", `<color=${acc}>[${title}]</color>`),
    ...m.opts,
    opt("Cooldown (seconds)", "Cooldown", n.cooldown),
    opt("Effect power", "EffectPower", n.power),
    opt("Effect duration (seconds)", "EffectSeconds", n.duration),
    opt("Effect radius (meters)", "EffectRadius", n.radius),
    ...fx.flatMap((f) => f.opts?.(n) ?? []),
  ];
  const opts = optPool.filter((o, i) => optPool.findIndex((p) => p.name === o.name) === i && scan.includes(`config.${o.name}`));
  const msgs = Object.fromEntries(
    Object.entries({ NoPermission: "You don't have permission to use this.", PlayerNotFound: "No player found matching '{0}'.", Cooldown: "Recharging, {0:0.0}s left.", ...m.msgs, ...Object.assign({}, ...fx.map((f) => f.msgs ?? {})) }).filter(([key]) => scan.includes(`"${key}"`)),
  );
  const usings = [
    "using System;",
    "using System.Collections.Generic;",
    "using System.Linq;",
    "using Newtonsoft.Json;",
    "using Oxide.Core;",
    /PluginReference/.test(scan) && "using Oxide.Core.Plugins;",
    /\bCui[A-Z]/.test(scan) && "using Oxide.Game.Rust.Cui;",
    /\b(DamageType|Layers)\./.test(scan) && "using Rust;",
    "using UnityEngine;",
    /\bRandom\./.test(scan) && "using Random = UnityEngine.Random;",
  ];

  const main = file(
    `plugins/${cls}.cs`,
    code`
      // ${title}: ${k} plugin for Rust, forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}.
      // Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
      ${input.version > 1 ? `// v${input.version}: retuned numbers; every value lives in config/${cls}.json.` : ""}
      ${usings}

      namespace Oxide.Plugins
      {
          [Info("${title}", "Cyrus", "${input.version}.0.0")]
          [Description("${m.desc.replace(/"/g, "'")}")]
          public class ${cls} : RustPlugin
          {
              ${join(
                region("Fields", fields.join("\n")),
                region("Oxide Hooks", join(lifecycle, m.hooks)),
                region("Commands", m.commands),
                region(m.label, m.logic ?? ""),
                region("Effects", effects || ""),
                region("API", api),
                region("Helpers", helperList.map(([, , body]) => body).join("\n\n")),
                region("Configuration", code`
                  private class Configuration
                  {
                      ${opts.map((o) => `[JsonProperty(${JSON.stringify(o.key)})]\npublic ${csType(o)} ${o.name} = ${csValue(o)};`).join("\n\n")}
                  }

                  protected override void LoadConfig()
                  {
                      base.LoadConfig();
                      try
                      {
                          config = Config.ReadObject<Configuration>();
                          if (config == null) throw new JsonException();
                          SaveConfig();
                      }
                      catch (Exception ex)
                      {
                          PrintError($"Config file is invalid ({ex.Message}); using defaults.");
                          LoadDefaultConfig();
                      }
                  }

                  protected override void LoadDefaultConfig() => config = new Configuration();

                  protected override void SaveConfig() => Config.WriteObject(config, true);`),
                region("Localization", block("protected override void LoadDefaultMessages()", [
                  `lang.RegisterMessages(new Dictionary<string, string>\n{\n${Object.entries(msgs).map(([key, v]) => `    [${JSON.stringify(key)}] = ${JSON.stringify(v)},`).join("\n")}\n}, this);`,
                ])),
              )}
          }
      }`,
  );

  const config = file(`config/${cls}.json`, `{\n${opts.map((o) => `  ${JSON.stringify(o.key)}: ${jsonValue(o).replace(/\n/g, "\n  ")}`).join(",\n")}\n}\n`);
  const l10n = file(`lang/en/${cls}.json`, JSON.stringify(msgs, null, 2) + "\n");
  const test = file(
    `tests/${cls}SelfTest.cs`,
    code`
      // Self-test harness for ${title}. Copy it next to ${cls}.cs in oxide/plugins, then run
      // \`${cmd}.selftest\` from the server console or RCON. Unload it again on live servers.
      using System.Collections.Generic;
      using Oxide.Core.Plugins;

      namespace Oxide.Plugins
      {
          [Info("${title} Self Test", "Cyrus", "${input.version}.0.0")]
          [Description("Checks that ${title} loaded with its permissions, messages and API")]
          public class ${cls}SelfTest : RustPlugin
          {
              [PluginReference] private Plugin ${cls};

              [ConsoleCommand("${cmd}.selftest")]
              private void CcmdSelfTest(ConsoleSystem.Arg arg)
              {
                  if (!arg.IsAdmin) return;
                  if (${cls} == null || !${cls}.IsLoaded) { arg.ReplyWith("${title} is not loaded"); return; }

                  var failures = new List<string>();
                  Check(failures, "permission ${lc}.use is registered", permission.PermissionExists("${lc}.use", ${cls}));
                  foreach (var key in new[] { ${Object.keys(msgs).slice(0, 4).map((key) => JSON.stringify(key)).join(", ")} })
                      Check(failures, $"message '{key}' is registered", lang.GetMessage(key, ${cls}) != key);
                  ${m.check}

                  arg.ReplyWith(failures.Count == 0 ? "${title}: all checks passed" : $"${title}: {failures.Count} failed\\n- " + string.Join("\\n- ", failures));
              }

              private static void Check(List<string> failures, string name, bool passed)
              {
                  if (!passed) failures.Add(name);
              }
          }
      }`,
  );

  return { files: [main, ...(m.extra ?? [])], config, l10n, test };
}

