const WEAPONISH = /rifle|rocket|launcher|railgun|pistol|shotgun|smg|\bak\b|bow|sword|spear|knife|c4|explosive/;
const RAID = /raid|alarm|\bbase\b|cupboard|\btc\b|code ?lock|door/;
