  [/scientist|companion|follower|bodyguard|\bnpc|bandit/, "characters"], [/monument|event|airdrop|oil ?rig|cargo/, "worlds"],
  [/gather|harvest|farm|quarry|rates?\b|loot/, "mechanics"], [/hud|\bui\b|overlay|scoreboard|panel/, "interface"],
];

export function rustOxide(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const title = input.modName.replace(/"/g, "'");
  const deep = input.model === "yako";
  const lc = cls.toLowerCase();
  const cmd = snake.split("_").slice(-2).join("");
  const acc = "#" + fxs[0].tint.map((c) => Math.round(c * 255).toString(16).padStart(2, "0")).join("");
  const tint = fxs[0].tint.map((c) => c.toFixed(2)).join(" ");
  const has = (key: EffectKey) => fxs.some((e) => e.key === key);
  const fxText = fxs.map((e) => e.label.toLowerCase()).join(" and ");

  let k = input.category.key;
  if (!input.category.keywords.some((w) => new RegExp(`\\b${w}`).test(text)) && !WEAPONISH.test(text)) k = INTENTS.find(([re]) => re.test(text))?.[1] ?? k;
  const arch = ARCH[k];
  const deny = (perm = "PermUse") => `if (!permission.UserHasPermission(player.UserIDString, ${perm})) { Reply(player, "NoPermission"); return; }`;
  const prefs = {
    fields: ["private HashSet<ulong> optedOut;"],
    init: ["optedOut = Interface.Oxide.DataFileSystem.ReadObject<HashSet<ulong>>(Name) ?? new HashSet<ulong>();"],
    save: ["Interface.Oxide.DataFileSystem.WriteObject(Name, optedOut);"],
  };
  const toggle = (refresh: string) => code`
    [ChatCommand("${cmd}")]
    private void CmdToggle(BasePlayer player, string command, string[] args)
    {
        ${deny()}
        var id = player.userID.Get();
        if (!optedOut.Remove(id)) optedOut.Add(id);
        ${refresh}
        Reply(player, optedOut.Contains(id) ? "Off" : "On");
    }`;
  const onConnect = (call: string) => code`
    private void OnPlayerConnected(BasePlayer player)
    {
        if (player.IsReceivingSnapshot) { timer.Once(1f, () => OnPlayerConnected(player)); return; }
        ${call}
    }`;

  let m: Mode;
  if (arch === "item") {
    const weapon = k === "weapons";
    const magic = k === "magic";
    const base = weapon ? pick(WEAPON_BASE, text, "rifle.ak") : magic ? pick(FOCUS_BASE, text, "bone.club") : pick(TOOL_BASE, text, "rock");
    m = {
      label: "Custom Item",
      desc: `${title}: a skinned ${base} that ${weapon ? "on hit" : magic ? "casts a spell that" : "has an ability that"} ${fxText}`,
      hooks: join(
        weapon
          ? code`
            private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
            {
                var attacker = info?.InitiatorPlayer;
                if (attacker == null || entity == null || !IsCustom(info.Weapon?.GetItem()) || !permission.UserHasPermission(attacker.UserIDString, PermUse)) return null;
                info.damageTypes.ScaleAll(${/pierc|wall|rail|breach|raid/.test(text) ? "entity is BuildingBlock ? config.StructureMultiplier : " : ""}config.DamageMultiplier);
                if (info.isHeadshot) EffectNetwork.Send(new Effect(FxHeadshot, attacker, 0, Vector3.zero, Vector3.zero), attacker.net.connection);
                if (Random.value <= config.ProcChance && !OnCooldown(attacker)) ApplyEffects(attacker, entity, info);
                return null;
            }

            private void OnLootSpawn(LootContainer container)
            {
                if (container == null || !config.LootContainers.Contains(container.ShortPrefabName) || Random.value > config.LootChance) return;
                NextTick(() =>
                {
                    if (container == null || container.IsDestroyed || container.inventory == null) return;
                    if (container.inventory.itemList.Count >= container.inventory.capacity) container.inventory.capacity++;
                    CreateItem()?.MoveToContainer(container.inventory);
                });
            }`
          : code`
            private void OnPlayerInput(BasePlayer player, InputState input)
            {
                if (player == null || input == null || !input.WasJustPressed(BUTTON.FIRE_THIRD)) return;
                var item = player.GetActiveItem();
                if (!IsCustom(item) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
                ${magic ? 'if (player.metabolism.calories.value < config.CalorieCost) { Reply(player, "Exhausted", config.CalorieCost); return; }' : ""}
                if (OnCooldown(player, true)) return;

                RaycastHit hit;
                ${
                  magic
                    ? code`
                      var point = Physics.Raycast(player.eyes.HeadRay(), out hit, config.Range, Layers.Solid) ? hit.point : player.eyes.position + player.eyes.HeadForward() * config.Range;
                      player.metabolism.calories.Subtract(config.CalorieCost);
                      Effect.server.Run(FxCast, point);
                      var caught = new List<BaseCombatEntity>();
                      Vis.Entities(point, config.EffectRadius, caught);
                      caught.RemoveAll(e => e == player || IsAlly(player, e as BasePlayer));
                      if (caught.Count == 0) ApplyEffects(player, null);
                      foreach (var target in caught) ApplyEffects(player, target);`
                    : code`
                      var target = Physics.Raycast(player.eyes.HeadRay(), out hit, config.Range, Layers.Solid | Layers.Mask.Player_Server) ? hit.GetEntity() as BaseCombatEntity : null;
                      ApplyEffects(player, target);
                      item.LoseCondition(config.ConditionCost);`
                }
            }

            private void OnItemCraftFinished(ItemCraftTask task, Item item, ItemCrafter crafter)
            {
                var player = task?.owner;
                if (player == null || item.info.shortname != config.Shortname || IsCustom(item) || Random.value > config.CraftChance) return;
                if (!permission.UserHasPermission(player.UserIDString, PermUse)) return;
                Brand(item);
                Reply(player, "Crafted", config.DisplayName);
            }`,
        code`
          private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
          {
              if (player != null && IsCustom(newItem) && permission.UserHasPermission(player.UserIDString, PermUse)) Reply(player, "Equipped", config.DisplayName);
          }`,
      ),
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdGive(BasePlayer player, string command, string[] args)
        {
            ${deny("PermAdmin")}
            var target = args.Length > 0 ? BasePlayer.Find(args[0]) : player;
            if (target == null) { Reply(player, "PlayerNotFound", args[0]); return; }
            var item = CreateItem();
            if (item == null) return;
            target.GiveItem(item);
            Reply(player, "Given", config.DisplayName, target.displayName);
        }`,
      logic: code`
        private Item CreateItem(int amount = 1)
        {
            var item = ItemManager.CreateByName(config.Shortname, amount, config.SkinId);
            if (item == null) PrintError($"Unknown item shortname '{config.Shortname}', check the config");
            else Brand(item);
            return item;
        }

        private void Brand(Item item)
        {
            item.skin = config.SkinId;
            item.name = config.DisplayName;
            var held = item.GetHeldEntity();
            if (held != null) { held.skinID = config.SkinId; held.SendNetworkUpdate(); }
            item.MarkDirty();
        }

        private bool IsCustom(Item item) => item != null && item.skin == config.SkinId && item.info.shortname == config.Shortname;`,
      opts: [
        opt("Item shortname", "Shortname", base), opt("Skin ID", "SkinId", 2_000_000_000 + (hashStr(cls) % 999_999_999), "ulong"), opt("Display name", "DisplayName", title),
        opt("Damage multiplier", "DamageMultiplier", r2(1 + n.power / 20)), opt("Damage multiplier vs. structures", "StructureMultiplier", r2(1.5 + n.power / 10)),
        opt("Effect chance per hit (0-1)", "ProcChance", n.chance), opt("Loot chance per crate (0-1)", "LootChance", r2(n.chance / 5)),
        opt("Loot containers", "LootContainers", ["crate_elite", "crate_normal", "heli_crate", "bradley_crate"]), opt("Craft chance (0-1)", "CraftChance", n.chance),
        opt("Range (meters)", "Range", n.radius * 8), opt("Condition lost per use", "ConditionCost", r2(n.power / 2)), opt("Calories per cast", "CalorieCost", Math.round(n.power * 5)),
      ],
      msgs: {
        Equipped: weapon ? `<color=${acc}>{0}</color> equipped: ${fxs.map((e) => e.label.toLowerCase()).join(", ")}.` : `<color=${acc}>{0}</color> in hand. Press <color=${acc}>middle mouse</color> to ${magic ? "cast" : "use it"}.`,
        Given: `Gave <color=${acc}>{0}</color> to {1}.`,
        Crafted: `Your craft turned out to be <color=${acc}>{0}</color>!`,
        Exhausted: "Too hungry to cast, you need {0} calories.",
      },
      api: "private Item API_CreateItem(int amount = 1) => CreateItem(amount);",
      check: `var item = ${cls}.Call("API_CreateItem", 1) as Item;\nCheck(failures, "API_CreateItem returns a branded item", item != null && item.skin != 0UL);\nitem?.Remove();`,
    };
  } else if (k === "creatures" || k === "characters") {
    // Wild mutants (creatures) and owned companions (characters) share one spawned-NPC registry.
    const pet = k === "characters";
    const prefab = pet ? `${SCIENTIST}peacekeeper.prefab` : `assets/rust.ai/agents/${pick(CREATURES, text, "bear/bear")}.prefab`;
    m = {
      label: pet ? "Companions" : "Mutants",
      desc: pet ? `${title}: a scientist companion that follows you and ${fxText}` : `${title}: mutated ${prefab.split("/").pop()!.replace(".prefab", "")}s with boosted health that ${fxText}`,
      fields: ["private readonly Dictionary<BaseCombatEntity, ulong> spawned = new Dictionary<BaseCombatEntity, ulong>();"],
      start: pet ? ["timer.Every(1f, Follow);"] : undefined,
      unload: ["foreach (var npc in spawned.Keys.ToList()) if (npc != null && !npc.IsDestroyed) npc.Kill();"],
      hooks: code`
        ${
          pet
            ? code`
              private void OnEntityTakeDamage(BasePlayer player, HitInfo info)
              {
                  var attacker = info?.Initiator as BaseCombatEntity;
                  var npc = CompanionOf(player.userID.Get());
                  if (npc == null || attacker == null || attacker == player || attacker == npc || IsAlly(player, attacker as BasePlayer)) return;
                  if (Vector3.Distance(npc.transform.position, attacker.transform.position) <= config.AssistRange) ApplyEffects(npc, attacker);
              }

              private void OnPlayerDisconnected(BasePlayer player, string reason) => CompanionOf(player.userID.Get())?.Kill();`
            : code`
              private void OnEntitySpawned(BaseCombatEntity entity)
              {
                  if (entity != null && entity.PrefabName == config.Prefab && Random.value <= config.SpawnChance) NextTick(() => Register(entity, 0UL));
              }

              private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
              {
                  var attacker = info?.Initiator as BaseCombatEntity;
                  if (attacker == null || !spawned.ContainsKey(attacker) || !(entity is BasePlayer)) return null;
                  info.damageTypes.ScaleAll(config.DamageMultiplier);
                  ApplyEffects(attacker, entity, info);
                  return null;
              }`
        }

        private void OnEntityDeath(BaseCombatEntity entity, HitInfo info)
        {
            ulong ownerId;
            if (entity == null || !spawned.TryGetValue(entity, out ownerId)) return;
            spawned.Remove(entity);
            ${
              pet
                ? 'summonOwners.Remove(entity.net.ID.Value);\nvar owner = BasePlayer.FindByID(ownerId);\nif (owner != null) Reply(owner, "Fallen", config.DisplayName);'
                : 'ItemManager.CreateByName(config.LootShortname, config.LootAmount)?.Drop(entity.transform.position + Vector3.up, Vector3.up * 2f);\nif (info?.InitiatorPlayer != null) Broadcast("Slain", info.InitiatorPlayer.displayName);'
            }
        }`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdSpawn(BasePlayer player, string command, string[] args)
        {
            ${deny(pet ? "PermUse" : "PermAdmin")}
            ${pet ? 'var current = CompanionOf(player.userID.Get());\nif (current != null) { current.Kill(); Reply(player, "Dismissed", config.DisplayName); return; }\nif (OnCooldown(player, true)) return;' : ""}
            var pos = player.transform.position + player.eyes.BodyForward() * ${pet ? 2 : 12}f;
            pos.y = TerrainMeta.HeightMap.GetHeight(pos);
            var npc = GameManager.server.CreateEntity(config.Prefab, pos) as BaseCombatEntity;
            if (npc == null) return;
            npc.Spawn();
            Register(npc, ${pet ? "player.userID.Get()" : "0UL"});
        }`,
      logic: join(
        code`
          private void Register(BaseCombatEntity npc, ulong ownerId)
          {
              if (npc == null || npc.IsDestroyed || spawned.ContainsKey(npc)) return;
              spawned[npc] = ownerId;
              npc.InitializeHealth(config.Health, config.Health);
              ${
                pet
                  ? 'var human = npc as BasePlayer;\nif (human != null) human.displayName = config.DisplayName;\nsummonOwners[npc.net.ID.Value] = ownerId;\nvar owner = BasePlayer.FindByID(ownerId);\nif (owner != null) Reply(owner, "Summoned", config.DisplayName, Name.ToLower());'
                  : 'npc.SendNetworkUpdate();\nif (config.Announce) Broadcast("Spawned", PhoneController.PositionToGridName(npc.transform.position));'
              }
          }`,
        pet &&
          code`
            private ScientistNPC CompanionOf(ulong ownerId) => spawned.FirstOrDefault(pair => pair.Value == ownerId).Key as ScientistNPC;

            private void Follow()
            {
                foreach (var pair in spawned.ToList())
                {
                    var npc = pair.Key as ScientistNPC;
                    var owner = BasePlayer.FindByID(pair.Value);
                    if (npc == null || owner == null) continue;
                    var distance = Vector3.Distance(npc.transform.position, owner.transform.position);
                    if (distance > config.LeashDistance) npc.Brain.Navigator.Warp(owner.transform.position - owner.eyes.BodyForward() * 2f);
                    else if (distance > config.FollowDistance) npc.Brain.Navigator.SetDestination(owner.transform.position, BaseNavigator.NavigationSpeed.Fast);
                }
            }`,
      ),
      opts: [
        opt(pet ? "Companion prefab" : "Creature prefab", "Prefab", prefab), opt(pet ? "Companion name" : "Display name", "DisplayName", title),
        opt("Mutation chance on natural spawns (0-1)", "SpawnChance", r2(n.chance / 2)), opt("Health", "Health", pet ? Math.round(n.health / 2) : n.health * 2),
        opt("Damage multiplier", "DamageMultiplier", r2(1 + n.power / 10)), opt("Loot shortname", "LootShortname", "scrap"), opt("Loot amount", "LootAmount", n.xp * 3, "int"),
        opt("Announce spawns", "Announce", true), opt("Follow distance (meters)", "FollowDistance", 4), opt("Teleport to owner beyond (meters)", "LeashDistance", n.radius * 8),
        opt("Assist range (meters)", "AssistRange", n.radius * 5), opt("Summon prefab", "SummonPrefab", prefab),
      ],
      msgs: pet
        ? { Summoned: `<color=${acc}>{0}</color> has your back. Type /{1} again to dismiss.`, Dismissed: "{0} heads home.", Fallen: `<color=${acc}>{0}</color> has fallen.` }
        : { Spawned: `A <color=${acc}>${title}</color> was sighted at {0}.`, Slain: `{0} brought down the <color=${acc}>${title}</color>.` },
      api: "private bool API_IsSpawned(BaseCombatEntity entity) => entity != null && spawned.ContainsKey(entity);",
      check: `Check(failures, "API_IsSpawned answers", ${cls}.Call("API_IsSpawned", (BaseCombatEntity)null) is bool);`,
    };
  } else if (k === "vehicles") {
    const prefab = /horse/.test(text) ? "assets/rust.ai/nextai/testridablehorse.prefab" : `assets/content/vehicles/${pick(VEHICLES, text, "modularcar/3module_car_spawned.entity.prefab")}`;
    m = {
      label: "Vehicles",
      desc: `${title}: a personal ${prefab.split("/").pop()!.replace(/(\.entity)?\.prefab/, "")} locked to your team, with a boost that ${fxText}`,
      fields: ["private readonly Dictionary<ulong, BaseVehicle> vehicles = new Dictionary<ulong, BaseVehicle>();"],
      unload: ["foreach (var vehicle in vehicles.Values) if (vehicle != null && !vehicle.IsDestroyed) vehicle.Kill();"],
      hooks: code`
        private object CanMountEntity(BasePlayer player, BaseMountable entity)
        {
            var vehicle = entity?.VehicleParent();
            if (vehicle == null || !config.LockToTeam || !vehicles.ContainsValue(vehicle)) return null;
            if (vehicle.OwnerID == player.userID.Get() || IsTeammate(vehicle.OwnerID, player)) return null;
            Reply(player, "Locked");
            return false;
        }

        private void OnEntityMounted(BaseMountable entity, BasePlayer player)
        {
            var vehicle = entity.VehicleParent();
            if (vehicle != null && vehicles.ContainsValue(vehicle) && vehicle.GetDriver() == player) Reply(player, "BoostHint");
        }

        private void OnPlayerInput(BasePlayer player, InputState input)
        {
            if (player == null || input == null || !input.WasJustPressed(BUTTON.FIRE_THIRD)) return;
            var vehicle = player.GetMountedVehicle();
            if (vehicle?.rigidBody == null || vehicle.GetDriver() != player || !vehicles.ContainsValue(vehicle) || OnCooldown(player, true)) return;

            vehicle.rigidBody.AddForce(vehicle.transform.forward * config.BoostForce, ForceMode.VelocityChange);
            Effect.server.Run(FxBoost, vehicle.transform.position);
            var ahead = new List<BasePlayer>();
            Vis.Entities(vehicle.transform.position + vehicle.transform.forward * 4f, config.EffectRadius, ahead, Layers.Mask.Player_Server);
            ApplyEffects(player, ahead.FirstOrDefault(p => !p.isMounted && !IsTeammate(player.userID.Get(), p)));
        }

        private void OnEntityKill(BaseVehicle vehicle)
        {
            var ownerId = vehicles.FirstOrDefault(pair => pair.Value == vehicle).Key;
            if (ownerId != 0UL) vehicles.Remove(ownerId);
        }`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdVehicle(BasePlayer player, string command, string[] args)
        {
            ${deny()}
            BaseVehicle vehicle;
            if (vehicles.TryGetValue(player.userID.Get(), out vehicle) && vehicle != null && !vehicle.IsDestroyed)
            {
                if (args.Length > 0 && args[0] == "despawn") vehicle.Kill();
                else Reply(player, "AlreadyOut", PhoneController.PositionToGridName(vehicle.transform.position), command);
                return;
            }
            if (player.IsBuildingBlocked()) { Reply(player, "BuildingBlocked"); return; }

            var pos = player.transform.position + player.eyes.BodyForward() * 4f + Vector3.up;
            vehicle = GameManager.server.CreateEntity(config.Prefab, pos, Quaternion.Euler(0f, player.eyes.rotation.eulerAngles.y, 0f)) as BaseVehicle;
            if (vehicle == null) return;
            vehicle.OwnerID = player.userID.Get();
            vehicle.Spawn();
            vehicles[player.userID.Get()] = vehicle;
            Reply(player, "Spawned", Title);
        }`,
      opts: [opt("Vehicle prefab", "Prefab", prefab), opt("Boost force (m/s)", "BoostForce", r2(n.speed * 30)), opt("Only owner and team can mount", "LockToTeam", true)],
      msgs: {
        Spawned: `Your <color=${acc}>{0}</color> is ready.`, AlreadyOut: "Your vehicle is parked at {0}. Use /{1} despawn to recall it.",
        BuildingBlocked: "You can't spawn a vehicle while building blocked.", Locked: "This vehicle is locked to its owner's team.", BoostHint: `Press <color=${acc}>middle mouse</color> to boost.`,
      },
      api: "private BaseVehicle API_GetVehicle(ulong userId)\n{\n    BaseVehicle vehicle;\n    return vehicles.TryGetValue(userId, out vehicle) ? vehicle : null;\n}",
      check: `Check(failures, "API_GetVehicle is empty for unknown players", ${cls}.Call("API_GetVehicle", 0UL) == null);`,
    };
  } else if (arch === "world") {
    m = {
      label: "Monument Event",
      desc: `${title}: a timed locked-crate event at a random monument inside a hostile zone`,
      fields: ["private readonly List<MonumentInfo> monuments = new List<MonumentInfo>();", "private readonly List<BaseEntity> guards = new List<BaseEntity>();", "private HackableLockedCrate crate;", "private Vector3 zone;", "private Timer pulse, expiry;"],
      start: [
        "monuments.AddRange(TerrainMeta.Path.Monuments.Where(monument => config.Monuments.Any(name => monument.name.Contains(name))));",
        'Puts($"{monuments.Count} monuments eligible for {Title}");',
        "timer.Every(config.IntervalMinutes * 60f, () => StartEvent());",
      ],
      unload: ["StopEvent(false);"],
      hooks: code`
        private void OnCrateHack(HackableLockedCrate hacked)
        {
            if (hacked != null && hacked == crate) Broadcast("Hacking", PhoneController.PositionToGridName(zone));
        }

        private void OnLootEntity(BasePlayer player, BaseEntity entity)
        {
            if (crate == null || entity != crate) return;
            Broadcast("Claimed", player.displayName);
            ${deep ? `Interface.CallHook("On${cls}Claimed", player, crate);` : ""}
            crate = null;
            StopEvent(true);
        }`,
      commands: code`
        [ChatCommand("${cmd}")]
        private void CmdEvent(BasePlayer player, string command, string[] args)
        {
            ${deny("PermAdmin")}
            if (args.Length > 0 && args[0] == "stop") StopEvent(false);
            else if (!StartEvent()) Reply(player, "CannotStart");
        }`,
      logic: code`
        private bool StartEvent()
        {
            if (crate != null || monuments.Count == 0 || BasePlayer.activePlayerList.Count < config.MinPlayers) return false;
            ${has("lunar") ? "if (config.NightOnly && !TOD_Sky.Instance.IsNight) return false;" : ""}
            var monument = monuments[Random.Range(0, monuments.Count)];
            zone = monument.transform.position;
            crate = GameManager.server.CreateEntity(PrefabCrate, zone + Vector3.up) as HackableLockedCrate;
            if (crate == null) return false;
            crate.Spawn();
            for (var i = 0; i < config.Guards; i++)
            {
                var spot = zone + Random.insideUnitSphere.WithY(0f) * 12f;
                spot.y = TerrainMeta.HeightMap.GetHeight(spot);
                var guard = GameManager.server.CreateEntity(config.GuardPrefab, spot);
                if (guard == null) continue;
                guard.Spawn();
                guards.Add(guard);
            }
            pulse = timer.Every(config.PulseSeconds, Pulse);
            expiry = timer.Once(config.DurationMinutes * 60f, () => StopEvent(false));
            Broadcast("Started", monument.displayPhrase.english, PhoneController.PositionToGridName(zone));
            return true;
        }

        // Every pulse, the zone itself turns on whoever is standing in it.
        private void Pulse()
        {
            var inside = new List<BasePlayer>();
            Vis.Entities(zone, config.ZoneRadius, inside, Layers.Mask.Player_Server);
            foreach (var player in inside) if (!player.IsNpc && player.IsAlive()) ApplyEffects(null, player);
        }

        private void StopEvent(bool claimed)
        {
            pulse?.Destroy();
            expiry?.Destroy();
            foreach (var guard in guards) if (guard != null && !guard.IsDestroyed) guard.Kill();
            guards.Clear();
            if (!claimed && crate != null && !crate.IsDestroyed)
            {
                crate.Kill();
                Broadcast("Expired");
            }
            crate = null;
        }`,
      opts: [
        opt("Event interval (minutes)", "IntervalMinutes", n.interval * 15), opt("Event duration (minutes)", "DurationMinutes", n.duration * 2),
        opt("Minimum online players", "MinPlayers", 2, "int"), opt("Only start at night", "NightOnly", true),
        opt("Monument filter", "Monuments", ["launch_site", "airfield", "military_tunnel", "powerplant", "trainyard", "water_treatment"]),
        opt("Zone radius (meters)", "ZoneRadius", n.radius * 10), opt("Zone pulse (seconds)", "PulseSeconds", Math.max(3, n.interval)),
        opt("Guards", "Guards", 2 + (n.radius % 4), "int"), opt("Guard prefab", "GuardPrefab", `${SCIENTIST}heavy.prefab`),
      ],
      msgs: {
        Started: `<color=${acc}>${title}</color>: a locked crate dropped at {0} ({1}). The zone ${fxs[0].label.toLowerCase().replace("the wielder", "you")}.`,
        Hacking: "Someone is hacking the crate at {0}!", Claimed: `{0} claimed the <color=${acc}>${title}</color> crate.`, Expired: `<color=${acc}>${title}</color> ended unclaimed.`,
        CannotStart: "Can't start: an event is running, no monuments matched or too few players are online.",
      },
      api: "private bool API_IsEventActive() => crate != null && !crate.IsDestroyed;",
      check: `Check(failures, "API_IsEventActive answers", ${cls}.Call("API_IsEventActive") is bool);`,
    };
  } else if (k === "mechanics" && !RAID.test(text) && /gather|harvest|farm|quarry|rate|loot|resource|auto/.test(text)) {
    const g = r2(1 + n.power / 5);
    m = {
      label: "Gather Rates",
      desc: `${title}: per-resource gather and pickup multipliers, plus a timer that ${fxText}`,
      start: [block("timer.Every(config.TickSeconds, () =>", ["foreach (var player in BasePlayer.activePlayerList)\n    if (permission.UserHasPermission(player.UserIDString, PermUse)) ApplyEffects(player, null);"]) + ");"],
      hooks: code`
        private void OnDispenserGather(ResourceDispenser dispenser, BaseEntity entity, Item item) => Scale(entity?.ToPlayer(), item);

        private void OnDispenserBonus(ResourceDispenser dispenser, BasePlayer player, Item item) => Scale(player, item);

        private void OnCollectiblePickup(CollectibleEntity collectible, BasePlayer player)
        {
            if (player == null || !permission.UserHasPermission(player.UserIDString, PermUse)) return;
