    [/\bIsAlly\(/, deep ? "[PluginReference] private Plugin Clans, Friends;" : undefined, code`
      private bool IsAlly(BasePlayer a, BasePlayer b)
      {
          if (a == null || b == null) return false;
          if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
          ${deep ? 'if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;\nreturn Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);' : "return false;"}
      }`],
    [/\bIsTeammate\(/, undefined, code`
      private static bool IsTeammate(ulong ownerId, BasePlayer player)
      {
          var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
          return player != null && team != null && team.members.Contains(player.userID.Get());
      }`],
    [/\bDamage\(/, undefined, code`
      private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
      {
          if (info != null) info.damageTypes.Add(type, amount);
          else target.Hurt(amount, type, attacker);
      }`],
    [/\bReply\(/, undefined, 'private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");'],
    [/\bBroadcast\(/, undefined, 'private void Broadcast(string key, params object[] args) => PrintToChat($"{config.ChatPrefix} {Lang(key, null, args)}");'],
    [/./, undefined, "private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);"],
  ];
  const api = input.model !== "katara" ? m.api : "";
  let scan = join(own, effects, api, ...(m.init ?? []), ...(m.unload ?? []));
  const used = new Set<number>();
  for (let pass = 0; pass < 3; pass++) helpers.forEach(([re, , body], i) => !used.has(i) && re.test(scan) && (used.add(i), (scan += "\n" + body)));
  const helperList = helpers.filter((_, i) => used.has(i));
  const uis = [...new Set(scan.match(/\bUi[A-Z]\w*/g) ?? [])];
  const admin = /\bPermAdmin\b/.test(scan);
  const fields = [
    `private const string PermUse = "${lc}.use";`,
    admin && `private const string PermAdmin = "${lc}.admin";`,
    ...Object.entries(ASSETS).filter(([name]) => new RegExp(`\\b${name}\\b`).test(scan)).map(([name, path]) => `private const string ${name} = "${path}";`),
    ...uis.map((ui) => `private const string ${ui} = "${cls}.${ui.slice(2)}";`),
    "\nprivate Configuration config;",
    ...(m.fields ?? []),
    ...helperList.map(([, field]) => field),
    fx.length > 0 && "private bool applying;",
  ].filter(Boolean);
  const unload = [
    ...(m.unload ?? []),
    ...(uis.length ? [block("foreach (var player in BasePlayer.activePlayerList)", uis.map((ui) => `CuiHelper.DestroyUi(player, ${ui});`))] : []),
    ...(m.save ? ["SaveData();"] : []),
  ];
  const lifecycle = join(
    block("private void Init()", ["permission.RegisterPermission(PermUse, this);", ...(admin ? ["permission.RegisterPermission(PermAdmin, this);"] : []), ...(m.init ?? [])]),
    m.start && block("private void OnServerInitialized()", m.start),
    m.save && `private void OnServerSave() => SaveData();\n\n${block("private void SaveData()", m.save)}`,
    unload.length > 0 && block("private void Unload()", unload),
  );
  scan += lifecycle;

  const optPool = [
    opt("Chat prefix", "ChatPrefix", `<color=${acc}>[${title}]</color>`),
    ...m.opts,
    opt("Cooldown (seconds)", "Cooldown", n.cooldown),
    opt("Effect power", "EffectPower", n.power),
    opt("Effect duration (seconds)", "EffectSeconds", n.duration),
    opt("Effect radius (meters)", "EffectRadius", n.radius),
    ...fx.flatMap((f) => f.opts?.(n) ?? []),
  ];
  const opts = optPool.filter((o, i) => optPool.findIndex((p) => p.name === o.name) === i && scan.includes(`config.${o.name}`));
  const msgs = Object.fromEntries(
    Object.entries({ NoPermission: "You don't have permission to use this.", PlayerNotFound: "No player found matching '{0}'.", Cooldown: "Recharging, {0:0.0}s left.", ...m.msgs, ...Object.assign({}, ...fx.map((f) => f.msgs ?? {})) }).filter(([key]) => scan.includes(`"${key}"`)),
  );
  const usings = [
    "using System;",
    "using System.Collections.Generic;",
    "using System.Linq;",
    "using Newtonsoft.Json;",
    "using Oxide.Core;",
    /PluginReference/.test(scan) && "using Oxide.Core.Plugins;",
    /\bCui[A-Z]/.test(scan) && "using Oxide.Game.Rust.Cui;",
    /\b(DamageType|Layers)\./.test(scan) && "using Rust;",
    "using UnityEngine;",
    /\bRandom\./.test(scan) && "using Random = UnityEngine.Random;",
  ];

  const main = file(
    `plugins/${cls}.cs`,
    code`
      // ${title}: ${k} plugin for Rust, forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}.
      // Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
      ${input.version > 1 ? `// v${input.version}: retuned numbers; every value lives in config/${cls}.json.` : ""}
      ${usings}

      namespace Oxide.Plugins
      {
          [Info("${title}", "Cyrus", "${input.version}.0.0")]
          [Description("${m.desc.replace(/"/g, "'")}")]
          public class ${cls} : RustPlugin
          {
              ${join(
                region("Fields", fields.join("\n")),
                region("Oxide Hooks", join(lifecycle, m.hooks)),
                region("Commands", m.commands),
                region(m.label, m.logic ?? ""),
                region("Effects", effects || ""),
                region("API", api),
                region("Helpers", helperList.map(([, , body]) => body).join("\n\n")),
                region("Configuration", code`
                  private class Configuration
                  {
                      ${opts.map((o) => `[JsonProperty(${JSON.stringify(o.key)})]\npublic ${csType(o)} ${o.name} = ${csValue(o)};`).join("\n\n")}
                  }

                  protected override void LoadConfig()
                  {
                      base.LoadConfig();
                      try
                      {
                          config = Config.ReadObject<Configuration>();
                          if (config == null) throw new JsonException();
                          SaveConfig();
                      }
                      catch (Exception ex)
                      {
                          PrintError($"Config file is invalid ({ex.Message}); using defaults.");
                          LoadDefaultConfig();
                      }
                  }

                  protected override void LoadDefaultConfig() => config = new Configuration();

                  protected override void SaveConfig() => Config.WriteObject(config, true);`),
                region("Localization", block("protected override void LoadDefaultMessages()", [
                  `lang.RegisterMessages(new Dictionary<string, string>\n{\n${Object.entries(msgs).map(([key, v]) => `    [${JSON.stringify(key)}] = ${JSON.stringify(v)},`).join("\n")}\n}, this);`,
                ])),
              )}
          }
      }`,
  );

  const config = file(`config/${cls}.json`, `{\n${opts.map((o) => `  ${JSON.stringify(o.key)}: ${jsonValue(o).replace(/\n/g, "\n  ")}`).join(",\n")}\n}\n`);
  const l10n = file(`lang/en/${cls}.json`, JSON.stringify(msgs, null, 2) + "\n");
  const test = file(
    `tests/${cls}SelfTest.cs`,
    code`
      // Self-test harness for ${title}. Copy it next to ${cls}.cs in oxide/plugins, then run
      // \`${cmd}.selftest\` from the server console or RCON. Unload it again on live servers.
      using System.Collections.Generic;
      using Oxide.Core.Plugins;

      namespace Oxide.Plugins
      {
          [Info("${title} Self Test", "Cyrus", "${input.version}.0.0")]
          [Description("Checks that ${title} loaded with its permissions, messages and API")]
          public class ${cls}SelfTest : RustPlugin
          {
              [PluginReference] private Plugin ${cls};

              [ConsoleCommand("${cmd}.selftest")]
              private void CcmdSelfTest(ConsoleSystem.Arg arg)
              {
                  if (!arg.IsAdmin) return;
                  if (${cls} == null || !${cls}.IsLoaded) { arg.ReplyWith("${title} is not loaded"); return; }

                  var failures = new List<string>();
                  Check(failures, "permission ${lc}.use is registered", permission.PermissionExists("${lc}.use", ${cls}));
                  foreach (var key in new[] { ${Object.keys(msgs).slice(0, 4).map((key) => JSON.stringify(key)).join(", ")} })
                      Check(failures, $"message '{key}' is registered", lang.GetMessage(key, ${cls}) != key);
                  ${m.check}

                  arg.ReplyWith(failures.Count == 0 ? "${title}: all checks passed" : $"${title}: {failures.Count} failed\\n- " + string.Join("\\n- ", failures));
              }

              private static void Check(List<string> failures, string name, bool passed)
              {
                  if (!passed) failures.Add(name);
              }
          }
      }`,
  );

  return { files: [main, ...(m.extra ?? [])], config, l10n, test };
}

toolu_018QEvm2HFy6gFvqp43w15kW.content:
/**
 * Rust · Oxide/uMod (Carbon-compatible) · C#. One plugin per mod; config/lang JSON mirror what Oxide writes on first
 * load. Branches on the archetype, and on Rust nouns ("raid alarm", "minicopter") when routing fell back to a default.
 */
import type { CategoryKey, ModFile } from "@/lib/types";
import { ARCH, code, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

type Nums = ReturnType<typeof numbers>;
type Val = number | string | boolean | string[] | Record<string, number>;
interface Opt { key: string; name: string; v: Val; t?: "int" | "ulong" }
interface Fx { apply: string; member?: string; opts?: (n: Nums) => Opt[]; msgs?: Record<string, string> }
interface Mode {
  desc: string;
  label: string;
  fields?: string[];
  init?: string[];
  start?: string[];
  save?: string[];
  unload?: string[];
  hooks: string;
  commands: string;
  logic?: string;
  opts: Opt[];
  msgs: Record<string, string>;
  api: string;
  check: string;
  extra?: ModFile[];
}

const opt = (key: string, name: string, v: Val, t?: Opt["t"]): Opt => ({ key, name, v, t });
const r2 = (x: number) => Math.round(x * 100) / 100;
const pick = (table: [RegExp, string][], text: string, fallback: string) => table.find(([re]) => re.test(text))?.[1] ?? fallback;
const join = (...parts: (string | false | undefined)[]) => parts.filter((p): p is string => !!p && !!p.trim()).map((p) => p.replace(/\n+$/, "")).join("\n\n");
const region = (name: string, body: string) => body.trim() && `#region ${name}\n\n${body.replace(/\n+$/, "")}\n\n#endregion`;
const block = (head: string, lines: string[]) => `${head}\n{\n${lines.map((l) => l.replace(/^/gm, "    ")).join("\n")}\n}`;
const jsonFloat = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));
const CS_TYPES: Record<string, string> = { number: "float", boolean: "bool", string: "string" };
const csType = (o: Opt) => o.t ?? CS_TYPES[typeof o.v] ?? (Array.isArray(o.v) ? "List<string>" : "Dictionary<string, float>");
function csValue({ v, t }: Opt) {
  if (typeof v === "number") return t ? `${v}${t === "ulong" ? "UL" : ""}` : `${v}f`;
  if (typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return `new List<string> { ${v.map((s) => JSON.stringify(s)).join(", ")} }`;
  return block("new Dictionary<string, float>", [Object.entries(v).map(([k, x]) => `[${JSON.stringify(k)}] = ${x}f`).join(",\n")]);
}
function jsonValue({ v, t }: Opt) {
  if (typeof v === "number") return t ? String(v) : jsonFloat(v);
  if (typeof v !== "object" || Array.isArray(v)) return JSON.stringify(v, null, 2);
  return `{\n${Object.entries(v).map(([k, x]) => `  ${JSON.stringify(k)}: ${jsonFloat(x)}`).join(",\n")}\n}`;
}

/** Real prefab paths; each becomes a const only when the generated plugin uses it. */
const ASSETS: Record<string, string> = {
  FxShock: "assets/prefabs/locks/keypad/effects/lock.code.shock.prefab",
  FxExplosion: "assets/bundled/prefabs/fx/explosions/explosion_03.prefab",
  FxBlink: "assets/prefabs/misc/halloween/lootbag/effects/silver_open.prefab",
  FxPoison: "assets/bundled/prefabs/fx/gestures/drink_vomit.prefab",
  FxCast: "assets/prefabs/misc/xmas/presents/effects/unwrap.prefab",
  FxHeadshot: "assets/bundled/prefabs/fx/headshot.prefab",
  FxAlarm: "assets/bundled/prefabs/fx/invite_notice.prefab",
  FxSuccess: "assets/prefabs/deployable/research table/effects/research-success.prefab",
  FxBoost: "assets/prefabs/npc/patrol helicopter/effects/rocket_fire.prefab",
  PrefabFireball: "assets/bundled/prefabs/fireball_small.prefab",
  PrefabCrate: "assets/prefabs/deployable/chinooklockedcrate/codelockedhackablecrate.prefab",
};
const SCIENTIST = "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_";

/** Each prompt effect as Oxide code inside ApplyEffects(attacker, target, info); `member` adds the hook/method it needs. */
const FX: Record<EffectKey, Fx> = {
  frost: { apply: code`
    // Frost: chill them to the bone; Rust's own cold damage does the rest.
    if (target != null) Damage(target, attacker, info, DamageType.Cold, config.EffectPower);
    if (victim != null)
    {
        victim.metabolism.temperature.SetValue(-config.EffectPower * 2f);
        victim.metabolism.wetness.Add(0.6f);
        victim.metabolism.SendChangesToClient();
    }` },
  fire: { apply: code`
    // Fire: leave a burning fireball where they stand.
    if (target != null) Damage(target, attacker, info, DamageType.Heat, config.EffectPower);
    var fireball = target != null ? GameManager.server.CreateEntity(PrefabFireball, pos) as FireBall : null;
    if (fireball != null)
    {
        fireball.lifeTimeMin = fireball.lifeTimeMax = config.EffectSeconds;
        fireball.Spawn();
    }` },
  storm: { apply: code`
    // Storm: shock the target, then arc to anyone standing close by.
    if (target != null)
    {
        Damage(target, attacker, info, DamageType.ElectricShock, config.EffectPower);
        Effect.server.Run(FxExplosion, pos);
        var arcs = new List<BasePlayer>();
        Vis.Entities(pos, config.EffectRadius, arcs, Layers.Mask.Player_Server);
        foreach (var other in arcs)
        {
            if (other == target || other == attacker || other.IsSleeping() || IsAlly(caster, other)) continue;
            Effect.server.Run(FxShock, other.transform.position);
            other.Hurt(config.EffectPower * 0.5f, DamageType.ElectricShock, attacker);
        }
    }` },
  blink: { apply: code`
    // Blink: step through space to just behind the target.
    if (caster != null && target != null && !caster.isMounted)
    {
        var behind = pos - target.transform.forward * 1.5f;
        behind.y = Mathf.Max(behind.y, TerrainMeta.HeightMap.GetHeight(behind));
        Effect.server.Run(FxBlink, caster.transform.position);
        caster.Teleport(behind);
        Effect.server.Run(FxBlink, behind);
    }` },
  heal: { apply: code`
    // Heal: every proc patches the attacker up and stops the bleeding.
    if (attacker != null && !attacker.IsDead()) attacker.Heal(config.EffectPower * 0.5f);
    if (caster != null) caster.metabolism.bleeding.SetValue(0f);` },
  poison: { apply: code`
    // Poison: venom keeps working long after the hit.
    if (victim != null) victim.metabolism.poison.Add(config.EffectPower);
    else if (target != null) Damage(target, attacker, info, DamageType.Poison, config.EffectPower);
    if (target != null) Effect.server.Run(FxPoison, pos);` },
  summon: {
    apply: code`
      // Summon: echoes spawn around the target and fight for the attacker.
      for (var i = 0; caster != null && i < config.SummonCount; i++)
      {
          var spot = pos + Random.insideUnitSphere.WithY(0f) * config.EffectRadius;
          spot.y = TerrainMeta.HeightMap.GetHeight(spot);
          var echo = GameManager.server.CreateEntity(config.SummonPrefab, spot) as BaseCombatEntity;
          if (echo == null) continue;
          echo.Spawn();
          var id = echo.net.ID.Value;
          summonOwners[id] = caster.userID.Get();
          timer.Once(config.EffectSeconds * 3f, () =>
          {
              summonOwners.Remove(id);
              if (echo != null && !echo.IsDestroyed) echo.Kill();
          });
      }`,
    opts: (n) => [opt("Summon count", "SummonCount", 1 + (n.radius % 3), "int"), opt("Summon prefab", "SummonPrefab", `${SCIENTIST}roam.prefab`)],
  },
  flight: {
    apply: code`
      // Flight: launch the attacker skywards, or the vehicle they're driving.
      var ride = caster?.GetMountedVehicle();
      if (ride != null && ride.rigidBody != null) ride.rigidBody.AddForce(Vector3.up * config.LiftForce, ForceMode.VelocityChange);
      else if (caster != null && !caster.isMounted) caster.ApplyInheritedVelocity(caster.eyes.HeadForward() * 4f + Vector3.up * config.LiftForce);`,
    opts: (n) => [opt("Lift force (m/s)", "LiftForce", r2(n.speed * 25))],
  },
  void: { apply: code`
    // Void: open a wound and black out their screen for a moment.
    if (target != null) Damage(target, attacker, info, DamageType.Bleeding, config.EffectPower * 0.5f);
    if (victim != null && victim.IsConnected)
    {
        victim.metabolism.bleeding.Add(config.EffectPower);
        var veil = new CuiElementContainer();
        veil.Add(new CuiPanel { Image = { Color = "0 0 0 0.94", FadeIn = 0.3f }, RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }, FadeOut = 1.5f }, "Overlay", UiVoid);
        CuiHelper.DestroyUi(victim, UiVoid);
        CuiHelper.AddUi(victim, veil);
        timer.Once(config.EffectSeconds, () => { if (victim != null && victim.IsConnected) CuiHelper.DestroyUi(victim, UiVoid); });
    }` },
  lunar: {
    apply: code`
      // Lunar: after dark every proc hits harder.
      if (target != null && TOD_Sky.Instance.IsNight)
      {
          if (info != null) info.damageTypes.ScaleAll(1f + config.NightBonus);
          else target.Hurt(config.EffectPower * config.NightBonus, DamageType.Generic, attacker);
          Effect.server.Run(FxCast, pos);
      }`,
    opts: (n) => [opt("Night damage bonus (0-1)", "NightBonus", r2(n.intensity / 2))],
  },
  auto: {
    apply: code`
      // Auto: the tool or weapon in hand repairs itself as it works.
      var held = caster?.GetActiveItem();
      if (held != null && held.hasCondition) held.condition = Mathf.Min(held.maxCondition, held.condition + config.EffectPower);`,
    member: code`
      private void OnDispenserGather(ResourceDispenser dispenser, BaseEntity entity, Item item)
      {
          var player = entity?.ToPlayer();
          if (player != null && permission.UserHasPermission(player.UserIDString, PermUse)) item.amount = Mathf.CeilToInt(item.amount * config.GatherMultiplier);
      }`,
    opts: (n) => [opt("Gather multiplier", "GatherMultiplier", r2(1 + n.power / 10))],
  },
  neon: {
    apply: code`
      // Neon: a HUD flash tells the attacker the effect fired.
      if (caster != null && caster.IsConnected) Flash(caster, Lang("Proc", caster.UserIDString, Title));`,
    member: code`
      private void Flash(BasePlayer player, string text)
      {
          var ui = new CuiElementContainer();
          ui.Add(new CuiPanel { Image = { Color = "1 0.4 0.85 0.85", FadeIn = 0.15f }, RectTransform = { AnchorMin = "0.38 0.86", AnchorMax = "0.62 0.91" }, FadeOut = 0.4f }, "Hud", UiFlash);
          ui.Add(new CuiLabel { Text = { Text = text, FontSize = 13, Align = TextAnchor.MiddleCenter, Font = "robotocondensed-bold.ttf" }, RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" } }, UiFlash);
          CuiHelper.DestroyUi(player, UiFlash);
          CuiHelper.AddUi(player, ui);
          timer.Once(2f, () => { if (player != null && player.IsConnected) CuiHelper.DestroyUi(player, UiFlash); });
      }`,
    msgs: { Proc: "<color=#ff66d9>{0}</color> overcharged" },
  },
};

const WEAPON_BASE: [RegExp, string][] = [
  [/crossbow/, "crossbow"], [/bow|arrow/, "bow.compound"], [/rail|sniper|pierc/, "rifle.l96"], [/shotgun|scatter/, "shotgun.spas12"], [/revolver|pistol/, "pistol.python"],
  [/smg|uzi/, "smg.mp5"], [/rocket|launcher/, "rocket.launcher"], [/flame/, "flamethrower"], [/sword|blade|katana/, "longsword"], [/axe/, "axe.salvaged"],
  [/hammer|mace/, "mace"], [/spear|glaive/, "spear.stone"], [/knife|dagger/, "knife.combat"],
];
const TOOL_BASE: [RegExp, string][] = [[/pick|mine|ore/, "pickaxe"], [/axe|chop|wood/, "hatchet"], [/heal|med|syringe|potion/, "syringe.medical"], [/torch|lantern|light/, "torch"], [/drill|jack/, "jackhammer"]];
const FOCUS_BASE: [RegExp, string][] = [[/staff|rod|wand/, "spear.wooden"], [/skull|necro/, "skull.human"], [/torch|flame|fire/, "torch"]];
const CREATURES: [RegExp, string][] = [[/polar/, "bear/polarbear"], [/wolf|hound/, "wolf/wolf"], [/boar|pig/, "boar/boar"], [/stag|deer/, "stag/stag"], [/shark/, "fish/simpleshark"], [/chicken/, "chicken/chicken"]];
const VEHICLES: [RegExp, string][] = [
  [/scrap|transport/, "scrap heli carrier/scraptransporthelicopter.prefab"], [/mini|copter|heli|fly|flight/, "minicopter/minicopter.entity.prefab"],
  [/rhib/, "boats/rhib/rhib.prefab"], [/boat|ship|raft|sea/, "boats/rowboat/rowboat.prefab"], [/submarine/, "submarine/submarinesolo.entity.prefab"],
  [/snow/, "snowmobiles/snowmobile.prefab"], [/bike|motor/, "bikes/motorbike.prefab"],
];
/** Rust nouns that pick the archetype when the router fell back to Rust's default category. */
const WEAPONISH = /rifle|rocket|launcher|railgun|pistol|shotgun|smg|\bak\b|bow|sword|spear|knife|c4|explosive/;
const RAID = /raid|alarm|\bbase\b|cupboard|\btc\b|code ?lock|door/;
const INTENTS: [RegExp, CategoryKey][] = [
  [RAID, "mechanics"], [/minicopter|copter|heli\b|rhib|boat|\bcar\b|bike|snowmobile|submarine|vehicle/, "vehicles"],
  [/scientist|companion|follower|bodyguard|\bnpc|bandit/, "characters"], [/monument|event|airdrop|oil ?rig|cargo/, "worlds"],
  [/gather|harvest|farm|quarry|rates?\b|loot/, "mechanics"], [/hud|\bui\b|overlay|scoreboard|panel/, "interface"],
];

export function rustOxide(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const title = input.modName.replace(/"/g, "'");
  const deep = input.model === "yako";
  const lc = cls.toLowerCase();
  const cmd = snake.split("_").slice(-2).join("");
  const acc = "#" + fxs[0].tint.map((c) => Math.round(c * 255).toString(16).padStart(2, "0")).join("");
  const tint = fxs[0].tint.map((c) => c.toFixed(2)).join(" ");
  const has = (key: EffectKey) => fxs.some((e) => e.key === key);
  const fxText = fxs.map((e) => e.label.toLowerCase()).join(" and ");

  let k = input.category.key;
  if (!input.category.keywords.some((w) => new RegExp(`\\b${w}`).test(text)) && !WEAPONISH.test(text)) k = INTENTS.find(([re]) => re.test(text))?.[1] ?? k;
  const arch = ARCH[k];
  const deny = (perm = "PermUse") => `if (!permission.UserHasPermission(player.UserIDString, ${perm})) { Reply(player, "NoPermission"); return; }`;
  const prefs = {
    fields: ["private HashSet<ulong> optedOut;"],
    init: ["optedOut = Interface.Oxide.DataFileSystem.ReadObject<HashSet<ulong>>(Name) ?? new HashSet<ulong>();"],
    save: ["Interface.Oxide.DataFileSystem.WriteObject(Name, optedOut);"],
  };
  const toggle = (refresh: string) => code`
    [ChatCommand("${cmd}")]
    private void CmdToggle(BasePlayer player, string command, string[] args)
    {
