// Railgun: weapons plugin for Rust, forged by Cyrus (Katara) v1.
// Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Oxide.Core;
using Rust;
using UnityEngine;
using Random = UnityEngine.Random;

namespace Oxide.Plugins
{
    [Info("Railgun", "Cyrus", "1.0.0")]
    [Description("Railgun: a skinned rifle.l96 that on hit freezes and slows what it hits")]
    public class Railgun : RustPlugin
    {
        #region Fields

        private const string PermUse = "railgun.use";
        private const string PermAdmin = "railgun.admin";
        private const string FxHeadshot = "assets/bundled/prefabs/fx/headshot.prefab";

        private Configuration config;
        private readonly Dictionary<ulong, float> cooldowns = new Dictionary<ulong, float>();
        private bool applying;

        #endregion

        #region Oxide Hooks

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            permission.RegisterPermission(PermAdmin, this);
        }

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            var attacker = info?.InitiatorPlayer;
            if (attacker == null || entity == null || !IsCustom(info.Weapon?.GetItem()) || !permission.UserHasPermission(attacker.UserIDString, PermUse)) return null;
            info.damageTypes.ScaleAll(entity is BuildingBlock ? config.StructureMultiplier : config.DamageMultiplier);
            if (info.isHeadshot) EffectNetwork.Send(new Effect(FxHeadshot, attacker, 0, Vector3.zero, Vector3.zero), attacker.net.connection);
            if (Random.value <= config.ProcChance && !OnCooldown(attacker)) ApplyEffects(attacker, entity, info);
            return null;
        }

        private void OnLootSpawn(LootContainer container)
        {
            if (container == null || !config.LootContainers.Contains(container.ShortPrefabName) || Random.value > config.LootChance) return;
            NextTick(() =>
            {
                if (container == null || container.IsDestroyed || container.inventory == null) return;
                if (container.inventory.itemList.Count >= container.inventory.capacity) container.inventory.capacity++;
                CreateItem()?.MoveToContainer(container.inventory);
            });
        }

        private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
        {
            if (player != null && IsCustom(newItem) && permission.UserHasPermission(player.UserIDString, PermUse)) Reply(player, "Equipped", config.DisplayName);
        }

        #endregion

        #region Commands

        [ChatCommand("railgun")]
        private void CmdGive(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermAdmin)) { Reply(player, "NoPermission"); return; }
            var target = args.Length > 0 ? BasePlayer.Find(args[0]) : player;
            if (target == null) { Reply(player, "PlayerNotFound", args[0]); return; }
            var item = CreateItem();
            if (item == null) return;
            target.GiveItem(item);
            Reply(player, "Given", config.DisplayName, target.displayName);
        }

        #endregion

        #region Custom Item

        private Item CreateItem(int amount = 1)
        {
            var item = ItemManager.CreateByName(config.Shortname, amount, config.SkinId);
            if (item == null) PrintError($"Unknown item shortname '{config.Shortname}', check the config");
            else Brand(item);
            return item;
        }

        private void Brand(Item item)
        {
            item.skin = config.SkinId;
            item.name = config.DisplayName;
            var held = item.GetHeldEntity();
            if (held != null) { held.skinID = config.SkinId; held.SendNetworkUpdate(); }
            item.MarkDirty();
        }

        private bool IsCustom(Item item) => item != null && item.skin == config.SkinId && item.info.shortname == config.Shortname;

        #endregion

        #region Effects

        private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)
        {
            if (applying || (attacker == null && target == null)) return;
            applying = true;
            try
            {
                var victim = target as BasePlayer;

                // Frost: chill them to the bone; Rust's own cold damage does the rest.
                if (target != null) Damage(target, attacker, info, DamageType.Cold, config.EffectPower);
                if (victim != null)
                {
                    victim.metabolism.temperature.SetValue(-config.EffectPower * 2f);
                    victim.metabolism.wetness.Add(0.6f);
                    victim.metabolism.SendChangesToClient();
                }

            }
            finally
            {
                applying = false;
            }
        }

        #endregion

        #region Helpers

        private bool OnCooldown(BasePlayer player, bool notify = false)
        {
            float readyAt;
            var now = Time.realtimeSinceStartup;
            if (cooldowns.TryGetValue(player.userID.Get(), out readyAt) && readyAt > now)
            {
                if (notify) Reply(player, "Cooldown", readyAt - now);
                return true;
            }
            cooldowns[player.userID.Get()] = now + config.Cooldown;
            return false;
        }

        private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
        {
            if (info != null) info.damageTypes.Add(type, amount);
            else target.Hurt(amount, type, attacker);
        }

        private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");

        private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);

        #endregion

        #region Configuration

        private class Configuration
        {
            [JsonProperty("Chat prefix")]
            public string ChatPrefix = "<color=#9edbff>[Railgun]</color>";

            [JsonProperty("Item shortname")]
            public string Shortname = "rifle.l96";

            [JsonProperty("Skin ID")]
            public ulong SkinId = 2425454443UL;

            [JsonProperty("Display name")]
            public string DisplayName = "Railgun";

            [JsonProperty("Damage multiplier")]
            public float DamageMultiplier = 1.69f;

            [JsonProperty("Damage multiplier vs. structures")]
            public float StructureMultiplier = 2.87f;

            [JsonProperty("Effect chance per hit (0-1)")]
            public float ProcChance = 0.2f;

            [JsonProperty("Loot chance per crate (0-1)")]
            public float LootChance = 0.04f;

            [JsonProperty("Loot containers")]
            public List<string> LootContainers = new List<string> { "crate_elite", "crate_normal", "heli_crate", "bradley_crate" };

            [JsonProperty("Cooldown (seconds)")]
            public float Cooldown = 3.6f;

            [JsonProperty("Effect power")]
            public float EffectPower = 13.7f;
        }

        protected override void LoadConfig()
        {
            base.LoadConfig();
            try
            {
                config = Config.ReadObject<Configuration>();
                if (config == null) throw new JsonException();
                SaveConfig();
            }
            catch (Exception ex)
            {
                PrintError($"Config file is invalid ({ex.Message}); using defaults.");
                LoadDefaultConfig();
            }
        }

        protected override void LoadDefaultConfig() => config = new Configuration();

        protected override void SaveConfig() => Config.WriteObject(config, true);

        #endregion

        #region Localization

        protected override void LoadDefaultMessages()
        {
            lang.RegisterMessages(new Dictionary<string, string>
            {
                ["NoPermission"] = "You don't have permission to use this.",
                ["PlayerNotFound"] = "No player found matching '{0}'.",
                ["Cooldown"] = "Recharging, {0:0.0}s left.",
                ["Equipped"] = "<color=#9edbff>{0}</color> equipped: freezes and slows what it hits.",
                ["Given"] = "Gave <color=#9edbff>{0}</color> to {1}.",
            }, this);
        }

        #endregion
    }
}

