import fs from "node:fs";
const p = "C:/Users/edmem/AppData/Roaming/Claude/scratch-workspaces/0a5c5ed9-8987-4824-aeb8-bdf4f706f10c/558b3c22-dbeb-42c0-ac92-8b838fdb343c/scratch-2026-10-07-d9846f/cyrus/lib/engine/games/rust.ts";
let s = fs.readFileSync(p, "utf8");
const rep = (a, b, all = false) => {
  if (!s.includes(a)) throw new Error("missing: " + a.slice(0, 80));
  s = all ? s.split(a).join(b) : s.replace(a, b);
};
// 1. Descriptions: no title prefix, better grammar.
rep('desc: `${title}: a skinned ${base} that ${weapon ? "on hit" : magic ? "casts a spell that" : "has an ability that"} ${fxText}`,',
  'desc: `A skinned ${base} ${weapon ? "that" : magic ? "whose spell" : "whose ability"} ${fxText}`,');
rep('desc: pet ? `${title}: a scientist companion that follows you and ${fxText}` : `${title}: mutated ${prefab.split("/").pop()!.replace(".prefab", "")}s with boosted health that ${fxText}`,',
  'desc: pet ? `A scientist companion that follows you, guards you and ${fxText}` : `Mutated ${prefab.split("/").pop()!.replace(".prefab", "")}s with boosted health; each one ${fxText}`,');
s = s.replace(/desc: `\$\{title\}: (\w)/g, (_, c) => "desc: `" + c.toUpperCase());
