// Usage: node rust-oxide-api.mjs "<prompt>" <model> [--print=path-substring] [--out=dir]
// Streams /api/generate, reassembles files from NDJSON chunk events and prints a summary (+ optional file bodies).
import fs from "node:fs";
import path from "node:path";
const args = process.argv.slice(2);
const [prompt, model = "yako"] = args.filter((a) => !a.startsWith("--"));
const print = args.find((a) => a.startsWith("--print="))?.slice(8);
const out = args.find((a) => a.startsWith("--out="))?.slice(6);
const res = await fetch("http://localhost:3000/api/generate", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt, model }) });
if (!res.ok) { console.log("HTTP", res.status, await res.text()); process.exit(1); }
const text = await res.text();
const files = new Map();
let route, done, errors = [];
for (const line of text.split("\n")) {
  if (!line.trim()) continue;
  const ev = JSON.parse(line);
  if (ev.type === "route") route = ev;
  if (ev.type === "file") files.set(ev.path, "");
  if (ev.type === "chunk") files.set(ev.path, (files.get(ev.path) ?? "") + ev.text);
  if (ev.type === "done") done = ev;
  if (ev.type === "error") errors.push(ev.message);
}
console.log(`# "${prompt}" [${model}] -> ${route?.gameId}/${route?.category} "${route?.modName}"${errors.length ? " ERRORS: " + errors.join("; ") : ""}`);
for (const [p, c] of files) console.log(`  ${p}  (${c.split("\n").length} lines)`);
if (out) for (const [p, c] of files) { const f = path.join(out, p); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, c); }
if (print) for (const [p, c] of files) if (p.includes(print)) console.log(`\n=== ${p}\n${c}`);

