// Smart Raid Alarms: mechanics plugin for Rust, forged by Cyrus (Yako) v1.
// Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Oxide.Core;
using Rust;
using UnityEngine;

namespace Oxide.Plugins
{
    [Info("Smart Raid Alarms", "Cyrus", "1.0.0")]
    [Description("Pings the base owner's team when their base is raided, logs the attacker and raid-blocks building")]
    public class SmartRaidAlarms : RustPlugin
    {
        #region Fields

        private const string PermUse = "smartraidalarms.use";
        private const string FxShock = "assets/prefabs/locks/keypad/effects/lock.code.shock.prefab";
        private const string FxExplosion = "assets/bundled/prefabs/fx/explosions/explosion_03.prefab";
        private const string FxAlarm = "assets/bundled/prefabs/fx/invite_notice.prefab";

        private Configuration config;
        private StoredData data;
        private readonly Dictionary<ulong, float> lastAlert = new Dictionary<ulong, float>();
        private readonly Dictionary<ulong, float> raidBlocked = new Dictionary<ulong, float>();
        [PluginReference] private Plugin Clans, Friends;
        private bool applying;

        #endregion

        #region Oxide Hooks

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            data = Interface.Oxide.DataFileSystem.ReadObject<StoredData>(Name) ?? new StoredData();
        }

        #region Effects

        private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)
        {
            if (applying || (attacker == null && target == null)) return;
            applying = true;
            try
            {
                var caster = attacker as BasePlayer;
                var pos = (target ?? attacker).transform.position;

                // Storm: shock the target, then arc to anyone standing close by.
                if (target != null)
                {
                    Damage(target, attacker, info, DamageType.ElectricShock, config.EffectPower);
                    Effect.server.Run(FxExplosion, pos);
                    var arcs = new List<BasePlayer>();
                    Vis.Entities(pos, config.EffectRadius, arcs, Layers.Mask.Player_Server);
                    foreach (var other in arcs)
                    {
                        if (other == target || other == attacker || other.IsSleeping() || IsAlly(caster, other)) continue;
                        Effect.server.Run(FxShock, other.transform.position);
                        other.Hurt(config.EffectPower * 0.5f, DamageType.ElectricShock, attacker);
                    }
                }
            }
            finally
            {
                applying = false;
            }
        }

        #endregion

        #region API

        private int API_GetRaidCount(ulong userId)
        {
            List<RaidEntry> log;
            return data.Logs.TryGetValue(userId, out log) ? log.Count : 0;
        }

        #endregion

        #region Helpers

        private bool IsAlly(BasePlayer a, BasePlayer b)
        {
            if (a == null || b == null) return false;
            if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
            if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;
            return Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);
        }

        private static bool IsTeammate(ulong ownerId, BasePlayer player)
        {
            var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
            return player != null && team != null && team.members.Contains(player.userID.Get());
        }

        private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
        {
            if (info != null) info.damageTypes.Add(type, amount);
            else target.Hurt(amount, type, attacker);
        }

        private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");

        private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);

        #endregion

        #region Configuration
{
  "Chat prefix": "<color=#b3bfff>[Smart Raid Alarms]</color>",
  "Alert cooldown per base (seconds)": 105.0,
  "Alert on melee damage": false,
  "Raid block (seconds)": 210.0,
  "Raid block radius for defenders (meters)": 60.0,
  "Log entries kept per player": 25,
  "Punish raiders with effects": false,
  "Effect power": 10.9,
  "Effect radius (meters)": 5.0
}

// Self-test harness for Mutant Bear Boss. Copy it next to MutantBearBoss.cs in oxide/plugins, then run
// `bearboss.selftest` from the server console or RCON. Unload it again on live servers.
using System.Collections.Generic;
using Oxide.Core.Plugins;

namespace Oxide.Plugins
{
    [Info("Mutant Bear Boss Self Test", "Cyrus", "1.0.0")]
    [Description("Checks that Mutant Bear Boss loaded with its permissions, messages and API")]
    public class MutantBearBossSelfTest : RustPlugin
    {
        [PluginReference] private Plugin MutantBearBoss;

        [ConsoleCommand("bearboss.selftest")]
        private void CcmdSelfTest(ConsoleSystem.Arg arg)
        {
            if (!arg.IsAdmin) return;
            if (MutantBearBoss == null || !MutantBearBoss.IsLoaded) { arg.ReplyWith("Mutant Bear Boss is not loaded"); return; }

            var failures = new List<string>();
            Check(failures, "permission mutantbearboss.admin is registered", permission.PermissionExists("mutantbearboss.admin", MutantBearBoss));
            foreach (var key in new[] { "NoPermission", "Spawned", "Slain" })
                Check(failures, $"message '{key}' is registered", lang.GetMessage(key, MutantBearBoss) != key);
            Check(failures, "API_IsSpawned answers", MutantBearBoss.Call("API_IsSpawned", (BaseCombatEntity)null) is bool);

            arg.ReplyWith(failures.Count == 0 ? "Mutant Bear Boss: all checks passed" : $"Mutant Bear Boss: {failures.Count} failed\n- " + string.Join("\n- ", failures));
        }

        private static void Check(List<string> failures, string name, bool passed)
        {
            if (!passed) failures.Add(name);
        }
    }
}
        #region HUD

        private void DrawHud(BasePlayer player)
        {
            if (player == null || !player.IsConnected) return;
            CuiHelper.DestroyUi(player, UiRoot);
            if (player.IsDead() || optedOut.Contains(player.userID.Get()) || !permission.UserHasPermission(player.UserIDString, PermUse)) return;

            var ui = new CuiElementContainer();
            var root = ui.Add(new CuiPanel { Image = { Color = config.Background }, RectTransform = { AnchorMin = config.AnchorMin, AnchorMax = config.AnchorMax } }, "Hud", UiRoot);
            var header = Lang("Header", player.UserIDString, PhoneController.PositionToGridName(player.transform.position), TOD_Sky.Instance.Cycle.DateTime.ToString("HH:mm"));
            ui.Add(new CuiLabel { Text = { Text = header, FontSize = 11, Align = TextAnchor.MiddleLeft, Color = config.Accent, Font = "robotocondensed-bold.ttf" }, RectTransform = { AnchorMin = "0.05 0.8", AnchorMax = "0.95 0.97" } }, root);

            var row = 0;
            foreach (var id in player.Team != null ? player.Team.members : new List<ulong> { player.userID.Get() })
            {
                var mate = BasePlayer.FindByID(id) ?? BasePlayer.FindSleeping(id);
                if (mate == null || row >= config.MaxRows) continue;
                var top = 0.78f - row++ * (0.74f / config.MaxRows);
                var bottom = top - 0.7f / config.MaxRows;
                var health = mate.IsDead() ? 0f : mate.health / mate.MaxHealth();
                ui.Add(new CuiLabel { Text = { Text = mate.displayName, FontSize = 10, Align = TextAnchor.MiddleLeft, Color = mate.IsConnected ? "1 1 1 0.9" : "1 1 1 0.4" }, RectTransform = { AnchorMin = $"0.05 {bottom:0.000}", AnchorMax = $"0.5 {top:0.000}" } }, root);
                var bar = ui.Add(new CuiPanel { Image = { Color = "1 1 1 0.08" }, RectTransform = { AnchorMin = $"0.52 {bottom + 0.02f:0.000}", AnchorMax = $"0.95 {top - 0.02f:0.000}" } }, root);
                ui.Add(new CuiPanel { Image = { Color = health < 0.3f ? "0.9 0.25 0.2 0.9" : config.Accent }, RectTransform = { AnchorMin = "0 0", AnchorMax = $"{health:0.00} 1" } }, bar);
            }
            CuiHelper.AddUi(player, ui);
        }

        #endregion
{
  "Chat prefix": "<color=#99ffb3>[Team HUD Overlay]</color>",
  "Refresh interval (seconds)": 3.0,
  "Anchor min": "0.005 0.72",
  "Anchor max": "0.17 0.92",
  "Background color": "0.08 0.08 0.1 0.72",
  "Accent color": "0.60 1.00 0.70 1",
  "Max teammate rows": 6
}
{
  "NoPermission": "You don't have permission to use this.",
  "Header": "TEAM HUD OVERLAY · {0} · {1}",
  "On": "<color=#99ffb3>HUD on.</color>",
  "Off": "HUD hidden. Type /hudoverlay to bring it back."
}

