// Self-test harness for Lightning Staff Spell. Copy it next to LightningStaffSpell.cs in oxide/plugins, then run
// `staffspell.selftest` from the server console or RCON. Unload it again on live servers.
using System.Collections.Generic;
using Oxide.Core.Plugins;

namespace Oxide.Plugins
{
    [Info("Lightning Staff Spell Self Test", "Cyrus", "1.0.0")]
    [Description("Checks that Lightning Staff Spell loaded with its permissions, messages and API")]
    public class LightningStaffSpellSelfTest : RustPlugin
    {
        [PluginReference] private Plugin LightningStaffSpell;

        [ConsoleCommand("staffspell.selftest")]
        private void CcmdSelfTest(ConsoleSystem.Arg arg)
        {
            if (!arg.IsAdmin) return;
            if (LightningStaffSpell == null || !LightningStaffSpell.IsLoaded) { arg.ReplyWith("Lightning Staff Spell is not loaded"); return; }

            var failures = new List<string>();
            Check(failures, "permission lightningstaffspell.use is registered", permission.PermissionExists("lightningstaffspell.use", LightningStaffSpell));
            foreach (var key in new[] { "NoPermission", "PlayerNotFound", "Cooldown", "Equipped" })
                Check(failures, $"message '{key}' is registered", lang.GetMessage(key, LightningStaffSpell) != key);
            var item = LightningStaffSpell.Call("API_CreateItem", 1) as Item;
            Check(failures, "API_CreateItem returns a branded item", item != null && item.skin != 0UL);
            item?.Remove();

            arg.ReplyWith(failures.Count == 0 ? "Lightning Staff Spell: all checks passed" : $"Lightning Staff Spell: {failures.Count} failed\n- " + string.Join("\n- ", failures));
        }

        private static void Check(List<string> failures, string name, bool passed)
        {
            if (!passed) failures.Add(name);
        }
    }
}

